const courses=[
 {id:'tribunal-juri-custodia',name:'Tribunal do Júri e Audiência de Custódia',area:'direito',image:'direito',position:'center 61%',desc:'Um olhar especializado sobre o júri e as audiências de custódia.',lead:'Aprofunde o estudo do Tribunal do Júri e das audiências de custódia, com atenção aos contextos, às garantias e aos desafios da atuação jurídica.',overviewTitle:'O conhecimento por trás da atuação no júri.',paragraphs:['O Tribunal do Júri e a audiência de custódia são espaços distintos da prática jurídica, com questões próprias de argumentação, análise de fatos e proteção de garantias. Esta especialização reúne esses campos em uma proposta de aprofundamento.', 'A formação tem como eixo o estudo das situações que atravessam esses procedimentos e a reflexão sobre o papel dos diferentes profissionais envolvidos.'],audience:'Uma área de interesse para graduados em Direito e profissionais que desejam estudar com maior profundidade o Tribunal do Júri e as audiências de custódia.',audienceTags:['Direito','Atuação jurídica','Estudo do processo penal'],topics:[['Tribunal do Júri','O júri como campo de estudo: seus contextos, atores, etapas e questões de argumentação.'],['Audiência de Custódia','Reflexão sobre a audiência de custódia e seus temas centrais, com atenção às garantias e às particularidades desse momento processual.'],['Perspectivas da atuação jurídica','Diálogo entre conhecimento jurídico, análise de situações e diferentes perspectivas sobre a atuação profissional.']],question:'Qual é o foco desta especialização?',answer:'O curso reúne o estudo do Tribunal do Júri e das audiências de custódia. A proposta completa e a organização curricular podem ser solicitadas à equipe FBE.'},
 {id:'direito-militar',name:'Direito Militar',area:'direito',image:'attorney',position:'center 33%',desc:'Conheça as particularidades de um campo próprio do Direito.',lead:'Explore o universo jurídico militar e suas particularidades, conectando o estudo da área às questões que fazem parte desse campo de atuação.',overviewTitle:'As particularidades do universo jurídico militar.',paragraphs:['O Direito Militar reúne temas e relações que pedem um repertório específico. Seu estudo permite compreender melhor os contextos institucionais e as questões que distinguem esse campo de outras áreas do Direito.', 'A especialização propõe um percurso de aprofundamento para quem deseja ampliar a leitura desse universo e organizar conhecimentos voltados à análise jurídica da área.'],audience:'Graduados em Direito e profissionais interessados em aprofundar o estudo das relações jurídicas no contexto militar.',audienceTags:['Direito','Contexto militar','Estudos jurídicos'],topics:[['Fundamentos do Direito Militar','Introdução aos conceitos e aos contextos que caracterizam o campo jurídico militar.'],['Relações e contextos institucionais','Estudo das particularidades das relações institucionais e de suas interfaces com o Direito.'],['Perspectivas de análise jurídica','Reflexão sobre problemas, debates e diferentes perspectivas de estudo na área militar.']],question:'A página apresenta a grade completa de Direito Militar?',answer:'Os temas apresentados ajudam a conhecer o campo da especialização. Solicite à equipe FBE a matriz curricular completa e os requisitos para ingresso.'},
 {id:'seguranca-publica',name:'Segurança Pública e Política Criminal',area:'direito',image:'penal',position:'center 46%',desc:'Segurança, instituições e sociedade em uma perspectiva integrada.',lead:'Amplie seu repertório para compreender a segurança pública e a política criminal, aproximando a análise institucional dos desafios da sociedade.',overviewTitle:'Segurança pública vista em suas diferentes dimensões.',paragraphs:['Pensar a segurança pública envolve observar instituições, dinâmicas sociais e escolhas de política criminal. Essa relação pede uma leitura que vá além de um único campo de conhecimento.', 'A proposta de especialização aproxima esses temas para favorecer uma compreensão mais ampla dos problemas, dos contextos e dos debates que atravessam a área.'],audience:'Graduados e profissionais interessados em segurança pública, política criminal e nas relações entre instituições e sociedade.',audienceTags:['Segurança Pública','Direito','Políticas públicas'],topics:[['Segurança pública e sociedade','Leitura dos contextos sociais e institucionais relacionados à segurança pública.'],['Política criminal','Discussão de perspectivas e debates sobre as escolhas que estruturam a política criminal.'],['Instituições e análise de contextos','Reflexão sobre as relações entre instituições, problemas públicos e diferentes formas de análise.']],question:'A especialização aborda segurança pública e política criminal juntas?',answer:'Sim. O nome do curso reúne esses dois campos de estudo. Consulte a apresentação completa para conhecer a organização dos temas e o perfil de ingresso.'},
 {id:'enfermagem-aph',name:'Enfermagem APH',area:'saude',image:'saude',position:'center 38%',desc:'Enfermagem e atendimento pré-hospitalar como campo de especialização.',lead:'Dedique-se ao estudo da enfermagem no atendimento pré-hospitalar e às particularidades desse contexto de cuidado.',overviewTitle:'Um campo específico da atuação em enfermagem.',paragraphs:['O atendimento pré-hospitalar tem contextos e demandas próprios. Para a enfermagem, essa área envolve organização do cuidado, comunicação e compreensão do ambiente em que o atendimento acontece.', 'A especialização direciona o olhar para esse campo, reunindo perspectivas de estudo relacionadas à enfermagem e ao atendimento fora do ambiente hospitalar.'],audience:'Profissionais da enfermagem interessados em aprofundar sua formação no campo do atendimento pré-hospitalar.',audienceTags:['Enfermagem','Atendimento Pré-Hospitalar','Saúde'],topics:[['Contextos do atendimento pré-hospitalar','Compreensão das características e dos diferentes cenários que fazem parte do atendimento pré-hospitalar.'],['Enfermagem e organização do cuidado','Reflexão sobre a presença da enfermagem e a organização do cuidado nesse contexto de atuação.'],['Comunicação e trabalho em equipe','Estudo das relações entre comunicação, equipes e continuidade do cuidado.']],question:'O que significa APH?',answer:'APH é a sigla de Atendimento Pré-Hospitalar. A especialização tem esse contexto como campo de interesse para a formação em enfermagem.'},
 {id:'enfermagem-mulher',name:'Enfermagem na Saúde da Mulher',area:'saude',image:'saude',position:'67% 44%',desc:'Um olhar dedicado à enfermagem e à saúde da mulher.',lead:'Aprofunde seu olhar sobre a saúde da mulher a partir da enfermagem, considerando contextos de cuidado, escuta e atenção às diferentes necessidades.',overviewTitle:'A saúde da mulher como campo de aprofundamento.',paragraphs:['A saúde da mulher pode ser compreendida a partir de diferentes contextos, necessidades e momentos da vida. A enfermagem ocupa um espaço importante nessa rede de cuidado.', 'Esta especialização propõe atenção a esse campo, conectando o estudo da saúde da mulher às perspectivas e às questões da formação em enfermagem.'],audience:'Profissionais da enfermagem interessados em direcionar sua formação ao cuidado e à saúde da mulher.',audienceTags:['Enfermagem','Saúde da Mulher','Cuidado em saúde'],topics:[['Perspectivas sobre a saúde da mulher','Estudo dos contextos que ajudam a compreender a saúde da mulher de maneira ampla.'],['Enfermagem e cuidado','Reflexão sobre as relações entre enfermagem, atenção e organização do cuidado.'],['Escuta e contextos de atenção','Discussão sobre escuta, necessidades e diferentes espaços de atenção à saúde.']],question:'Qual é a relação entre enfermagem e saúde da mulher neste curso?',answer:'A especialização reúne esses dois campos em uma proposta de aprofundamento. A apresentação completa detalha a organização curricular e o perfil de ingresso.'},
 {id:'direito-penal-processo',name:'Direito Penal e Processo Penal',area:'direito',image:'penal',position:'center 67%',desc:'Conecte o estudo penal à compreensão do processo.',lead:'Aprofunde seus conhecimentos nos campos penal e processual penal, ampliando a compreensão das relações entre conceitos, contextos e atuação jurídica.',overviewTitle:'Direito Penal e processo em uma mesma perspectiva.',paragraphs:['O estudo do Direito Penal se relaciona à compreensão do processo penal e dos diferentes contextos em que as questões jurídicas são discutidas. Aproximar esses campos contribui para uma leitura mais articulada da área.', 'A especialização organiza uma proposta de aprofundamento voltada a quem deseja desenvolver seu repertório de estudo e análise nos campos penal e processual penal.'],audience:'Graduados em Direito e profissionais interessados em aprofundar sua formação nas áreas penal e processual penal.',audienceTags:['Direito Penal','Processo Penal','Atuação jurídica'],topics:[['Perspectivas do Direito Penal','Aprofundamento de conceitos e debates que fazem parte do estudo do Direito Penal.'],['Estudo do processo penal','Compreensão das relações processuais e dos contextos de discussão na área penal.'],['Análise e argumentação jurídica','Reflexão sobre as conexões entre conhecimento, leitura de contextos e argumentação jurídica.']],question:'O curso combina Direito Penal e Processo Penal?',answer:'A proposta reúne os dois campos de estudo. Solicite a matriz curricular completa para conhecer os componentes e a organização da especialização.'},
 {id:'educacao',name:'Especialização em Educação',area:'educacao',image:'educacao',position:'center 41%',desc:'Amplie suas perspectivas sobre formação, ensino e aprendizagem.',lead:'Explore os desafios da educação e amplie seu repertório sobre formação, ensino, aprendizagem e os contextos em que essas relações acontecem.',overviewTitle:'Educação como campo de reflexão e formação.',paragraphs:['A educação se realiza em diferentes espaços e relações. Seus desafios envolvem compreender sujeitos, contextos e maneiras de construir o conhecimento.', 'Esta especialização propõe um campo de aprofundamento para quem deseja voltar o olhar à formação educacional e ampliar suas perspectivas de estudo sobre ensinar e aprender.'],audience:'Graduados e profissionais interessados em educação, formação e nos diferentes contextos de ensino e aprendizagem.',audienceTags:['Educação','Ensino e aprendizagem','Formação'],topics:[['Fundamentos da educação','Leitura de conceitos e perspectivas que ajudam a compreender a educação como campo de conhecimento.'],['Ensino e aprendizagem','Reflexão sobre os processos de ensinar e aprender e suas diferentes relações.'],['Contextos educacionais','Discussão sobre sujeitos, espaços e desafios presentes nos contextos da educação.']],question:'Qual é o campo de interesse desta especialização?',answer:'A educação é o eixo central da proposta. A apresentação completa informa o recorte do curso, sua organização e os requisitos para ingresso.'},
 {id:'direitos-mulheres',name:'Direitos Humanos das Mulheres',area:'humanos',image:'humanos',position:'center 43%',desc:'Direitos humanos, mulheres e sociedade como campo de estudo.',lead:'Aprofunde sua reflexão sobre os direitos humanos das mulheres e suas relações com a sociedade, as instituições e os diferentes contextos de reconhecimento de direitos.',overviewTitle:'Um olhar atento aos direitos humanos das mulheres.',paragraphs:['O estudo dos direitos humanos das mulheres envolve diferentes dimensões da vida social e institucional. Esse campo reúne debates sobre reconhecimento, participação e formas de compreender os direitos.', 'A especialização propõe um percurso de reflexão e aprofundamento para quem deseja ampliar o repertório de análise dessas questões.'],audience:'Graduados e profissionais interessados em direitos humanos, direitos das mulheres e em suas interfaces sociais e institucionais.',audienceTags:['Direitos Humanos','Direitos das Mulheres','Sociedade'],topics:[['Fundamentos dos direitos humanos','Compreensão de conceitos e perspectivas que orientam o estudo dos direitos humanos.'],['Direitos humanos das mulheres','Aprofundamento das questões que caracterizam esse campo de reflexão e conhecimento.'],['Perspectivas sociais e institucionais','Leitura dos contextos e das relações entre sociedade, instituições e reconhecimento de direitos.']],question:'O foco é o estudo dos direitos humanos das mulheres?',answer:'Sim. Esse é o campo central da especialização. A organização curricular e o recorte da formação podem ser conhecidos na apresentação completa do curso.'},
 {id:'perspectiva-genero',name:'Perspectiva de Gênero',area:'humanos',image:'humanos',position:'center 58%',desc:'Estude as relações de gênero em seus diferentes contextos.',lead:'Amplie seu repertório de estudo sobre gênero e sociedade, explorando perspectivas e contextos que fazem parte desse campo de conhecimento.',overviewTitle:'Perspectivas para compreender gênero e sociedade.',paragraphs:['As relações de gênero podem ser estudadas em diferentes dimensões da vida social. A análise desse campo envolve observar contextos, instituições e perspectivas de conhecimento.', 'A proposta de especialização reúne esse interesse em uma formação voltada ao aprofundamento da reflexão e à ampliação do repertório sobre o tema.'],audience:'Graduados e profissionais interessados no estudo das relações de gênero e de suas interfaces com a sociedade e as instituições.',audienceTags:['Perspectiva de Gênero','Sociedade','Direitos Humanos'],topics:[['Gênero e sociedade','Estudo das relações entre gênero, contextos sociais e diferentes perspectivas de análise.'],['Perspectivas de conhecimento','Reflexão sobre conceitos, debates e formas de compreender as relações de gênero.'],['Contextos institucionais','Análise de interfaces entre o tema, as instituições e os espaços da vida social.']],question:'Como conhecer melhor o recorte desta especialização?',answer:'Solicite a apresentação do curso à equipe FBE. Ela detalha o campo de estudo, a organização curricular e os requisitos para ingresso.'},
 {id:'gestao-estrategica',name:'Gestão Estratégica',area:'gestao',image:'gestao',position:'center 50%',desc:'Amplie a leitura das organizações e das decisões estratégicas.',lead:'Desenvolva seu repertório para compreender organizações, analisar contextos e refletir sobre os caminhos da gestão e da estratégia.',overviewTitle:'Um olhar mais amplo para a gestão.',paragraphs:['A gestão estratégica pede compreensão das organizações e do contexto em que elas atuam. Pensar seus caminhos envolve relacionar objetivos, escolhas e diferentes perspectivas de análise.', 'A especialização propõe um campo de aprofundamento para quem deseja ampliar seu repertório sobre gestão e a construção de decisões estratégicas.'],audience:'Graduados e profissionais interessados em gestão, estratégia e análise de contextos organizacionais.',audienceTags:['Gestão','Estratégia','Organizações'],topics:[['Análise organizacional','Compreensão das organizações, de seus contextos e dos elementos que participam da gestão.'],['Pensamento estratégico','Reflexão sobre objetivos, escolhas e perspectivas para a construção de caminhos estratégicos.'],['Gestão e tomada de decisão','Estudo das relações entre informação, análise e decisão no contexto organizacional.']],question:'Como conheço a organização da pós em Gestão Estratégica?',answer:'Solicite a apresentação completa do curso para conhecer a organização curricular e os detalhes da formação.'}
];

const curriculaData={"educacao":{"officialName":"Educação Afrocentrada, Tecnologias e Territórios","declaredHours":360,"components":[{"name":"Fundamentos da Educação Afrocentrada e Afrocentricidade","hours":30,"summary":"Apresenta os fundamentos da afrocentricidade e o lugar do sujeito na produção do conhecimento. Relaciona epistemologias africanas e afrodiaspóricas à leitura crítica das práticas educativas. Discute como referências, narrativas e escolhas curriculares podem reconhecer a agência de pessoas negras e ampliar as perspectivas presentes no ensino.","summaryOrigin":"editorial"},{"name":"Ancestralidade, Memória e Identidades Negras","hours":30,"summary":"Investiga as relações entre ancestralidade, memória coletiva e construção das identidades negras. Aborda a transmissão de saberes pela oralidade, pelo corpo, pela literatura e pelas manifestações culturais. Relaciona essas experiências ao pertencimento e à elaboração de práticas educativas que valorizem histórias familiares, comunitárias e territoriais.","summaryOrigin":"editorial"},{"name":"Educação para as Relações Étnico-Raciais e Legislação","hours":30,"summary":"Analisa a educação das relações étnico-raciais a partir das reivindicações do movimento negro e dos marcos legais apresentados no curso. Discute a presença da história e da cultura africana e afro-brasileira no currículo. Examina caminhos para reconhecer o racismo no cotidiano escolar e construir propostas pedagógicas comprometidas com a equidade.","summaryOrigin":"editorial"},{"name":"Educação Quilombola, Território e Saberes Comunitários","hours":30,"summary":"Estuda a educação quilombola em diálogo com território, memória e formas de organização comunitária. Examina os vínculos entre saberes locais, pertencimento e práticas de ensino. Discute a elaboração de ações educativas que reconheçam os sujeitos das comunidades, respeitem seus contextos e aproximem os conhecimentos escolares das experiências vividas.","summaryOrigin":"editorial"},{"name":"História e Cultura Africana e Afro-Brasileira","hours":30,"summary":"Explora a diversidade histórica das sociedades africanas e suas relações com a formação do Brasil. Aborda diásporas, escravização, resistências e produção cultural afro-brasileira. Discute escolhas de fontes e abordagens para tratar esses processos na educação, evitando visões homogêneas e reconhecendo o protagonismo de diferentes povos e sujeitos.","summaryOrigin":"editorial"},{"name":"Tecnologias Educacionais e Inteligência Artificial","hours":30,"summary":"Discute o uso pedagógico das tecnologias digitais e da inteligência artificial na organização do ensino. Examina planejamento, autoria, seleção de recursos e avaliação de conteúdos. Relaciona essas ferramentas à inclusão, à representação e aos cuidados éticos necessários para que a tecnologia dialogue com os objetivos educativos e com os contextos dos estudantes.","summaryOrigin":"editorial"},{"name":"Multiletramentos, Comunicação e Cultura Digital","hours":30,"summary":"Aborda os multiletramentos como práticas de leitura e produção de sentidos em diferentes linguagens. Examina textos, imagens, sons e interações nas culturas digitais. Discute como comunicação, identidade e circulação de informações podem orientar propostas educativas que ampliem a expressão dos estudantes e a análise crítica dos conteúdos com que convivem.","summaryOrigin":"editorial"},{"name":"Podcast, Audiovisual e Produção de Conteúdos","hours":30,"summary":"Apresenta as possibilidades do podcast e do audiovisual na comunicação de conhecimentos e experiências educativas. Aborda pesquisa de pauta, roteiro, entrevista e organização da narrativa. Discute a relação entre linguagem, público e finalidade pedagógica, com atenção à autoria, à escuta e à representação dos sujeitos presentes nos conteúdos produzidos.","summaryOrigin":"editorial"},{"name":"Laboratório de Projetos Afrocentrados","hours":40,"summary":"Articula os fundamentos da educação afrocentrada ao desenvolvimento de projetos educativos. Aborda a identificação de problemas, a leitura do contexto e a definição de objetivos e ações. Discute a coerência entre proposta, participantes e território, além de formas de acompanhar o percurso e registrar os aprendizados e os resultados do trabalho realizado.","summaryOrigin":"editorial"},{"name":"Aulas de Campo e Cartografia Cultural de Salvador","hours":20,"summary":"Relaciona educação patrimonial, leitura do território e cartografia cultural de Salvador. Aborda a preparação das experiências de campo, a observação e o registro de espaços, memórias e manifestações culturais. Discute como transformar esses registros em conhecimento, reconhecendo os sujeitos dos territórios e articulando a vivência fora da sala às questões educativas.","summaryOrigin":"editorial"},{"name":"Empreendedorismo Negro, Cultura e Economia Criativa","hours":20,"summary":"Examina a produção cultural negra e as desigualdades no acesso a oportunidades e recursos. Relaciona empreendedorismo, redes de colaboração e economia criativa às experiências dos territórios. Discute a organização de iniciativas culturais e educativas, considerando identidade, sustentabilidade e circulação de produtos e saberes em diferentes contextos sociais.","summaryOrigin":"editorial"},{"name":"Metodologia da Pesquisa e Produção Científica","hours":20,"summary":"Apresenta as etapas de construção de uma pesquisa no campo da educação, da pergunta inicial à organização dos resultados. Aborda objetivos, revisão de literatura, escolha de métodos e avaliação das fontes. Discute a relação entre problema, evidências e escrita acadêmica, com atenção à ética, às referências e à comunicação clara do conhecimento produzido.","summaryOrigin":"editorial"},{"name":"Projeto Final Produto ou Intervenção","hours":20,"summary":"Orienta a articulação dos conhecimentos do curso em um produto educativo ou em uma proposta de intervenção. Discute a coerência entre o problema identificado, os objetivos e as escolhas de desenvolvimento. Aborda o registro do percurso e a elaboração do memorial analítico, permitindo apresentar as decisões tomadas e avaliar a contribuição do trabalho para seu contexto.","summaryOrigin":"editorial"}],"sumHours":360,"source":"FBE LUANA MARINHO.docx","notes":[],"hasTotalConflict":false},"enfermagem-aph":{"officialName":"Enfermagem em Atendimento Pré-Hospitalar Móvel, Urgência e Emergência","declaredHours":360,"components":[{"name":"Fundamentos do Atendimento Pré-Hospitalar Móvel","hours":30,"summary":"Apresenta os fundamentos do atendimento pré-hospitalar móvel e sua articulação com a rede de urgência. Examina o papel da enfermagem na avaliação das necessidades de cuidado, na organização da assistência e na continuidade do atendimento. Discute as particularidades do ambiente externo e os critérios de segurança que orientam a atuação junto à equipe e ao paciente.","summaryOrigin":"editorial"},{"name":"Organização, Gestão e Operacionalização de Ambulâncias","hours":15,"summary":"Estuda a organização das ambulâncias e os processos que sustentam o funcionamento do atendimento móvel. Aborda planejamento de recursos, disponibilidade de materiais, registros e articulação entre serviços. Relaciona a gestão das operações à segurança assistencial, à comunicação com as equipes e à preparação do ambiente para diferentes demandas de urgência.","summaryOrigin":"editorial"},{"name":"Avaliação do Paciente e Abordagem Sistemática no APH","hours":30,"summary":"Explora a avaliação do paciente no contexto pré-hospitalar, com atenção à identificação de riscos e à definição de prioridades de cuidado. Relaciona observação clínica, coleta de informações e reavaliação ao longo do atendimento. Discute como organizar achados relevantes e comunicá-los à equipe para favorecer decisões e a continuidade da assistência no serviço de destino.","summaryOrigin":"editorial"},{"name":"Suporte Básico de Vida e Parada Cardiorrespiratória","hours":30,"summary":"Aborda os fundamentos do suporte básico de vida e a assistência de enfermagem nas situações de parada cardiorrespiratória. Discute reconhecimento da emergência, organização da resposta e atuação coordenada da equipe. Relaciona os temas à qualidade do atendimento e à segurança do paciente, considerando as características do ambiente pré-hospitalar e a continuidade do cuidado.","summaryOrigin":"editorial"},{"name":"Suporte Avançado de Vida e Cuidados Pós-Ressuscitação","hours":30,"summary":"Examina os princípios do suporte avançado de vida e os cuidados de enfermagem após a ressuscitação. Relaciona avaliação, monitorização e identificação de alterações clínicas à organização da assistência. Discute a integração entre os profissionais e a transferência de informações, com foco na segurança e no acompanhamento das necessidades do paciente durante o atendimento móvel.","summaryOrigin":"editorial"},{"name":"Atendimento ao Trauma e ao Politraumatizado","hours":30,"summary":"Estuda a assistência de enfermagem às vítimas de trauma e às pessoas com múltiplas lesões. Aborda a avaliação das condições do atendimento, a identificação de prioridades e o acompanhamento do paciente. Relaciona os cuidados à segurança da cena, ao trabalho em equipe e à organização do transporte, considerando os riscos envolvidos na continuidade da assistência.","summaryOrigin":"editorial"},{"name":"Emergências Cardiovasculares e Hemodinâmicas","hours":30,"summary":"Explora as principais situações cardiovasculares e hemodinâmicas encontradas no atendimento de urgência. Relaciona sinais clínicos e dados de monitorização à identificação de necessidades de cuidado. Discute a atuação da enfermagem na observação, nos registros e na comunicação das alterações, favorecendo a integração da equipe e a segurança durante o atendimento e o transporte.","summaryOrigin":"editorial"},{"name":"Emergências Respiratórias e Manejo das Vias Aéreas","hours":30,"summary":"Aborda a avaliação das condições respiratórias e os fundamentos relacionados à manutenção das vias aéreas no APH. Examina a identificação de alterações e o acompanhamento da resposta do paciente à assistência. Discute o papel da enfermagem na preparação de recursos, na monitorização e na comunicação com a equipe, considerando os limites e os riscos do ambiente móvel.","summaryOrigin":"editorial"},{"name":"Emergências Neurológicas, Metabólicas e Clínicas","hours":30,"summary":"Estuda situações neurológicas, metabólicas e clínicas que exigem atendimento de urgência fora do hospital. Relaciona história, sinais e evolução do quadro à organização das prioridades assistenciais. Discute a observação de alterações, os registros e a passagem de informações, com atenção à atuação da enfermagem e à continuidade do cuidado na rede de atendimento.","summaryOrigin":"editorial"},{"name":"Emergências Pediátricas e Obstétricas no APH","hours":25,"summary":"Examina as particularidades da assistência pré-hospitalar a crianças e a pacientes em situações obstétricas. Relaciona características de cada grupo à avaliação, à comunicação e às necessidades de cuidado. Discute a organização da equipe e dos recursos, o acolhimento dos acompanhantes e os cuidados com a segurança durante o atendimento e o encaminhamento ao serviço de referência.","summaryOrigin":"editorial"},{"name":"Transporte e Transferência do Paciente Crítico","hours":25,"summary":"Aborda o transporte e a transferência de pessoas em condição clínica crítica. Discute planejamento, preparação de recursos, monitorização e comunicação entre os serviços envolvidos. Relaciona a assistência de enfermagem à identificação de riscos durante o percurso e à organização dos registros, buscando preservar a continuidade e a segurança do cuidado até a recepção do paciente.","summaryOrigin":"editorial"},{"name":"Segurança, Biossegurança, Ética e Aspectos Legais no APH","hours":15,"summary":"Relaciona segurança ocupacional, biossegurança e responsabilidade profissional às situações do atendimento móvel. Examina riscos do ambiente, proteção da equipe, confidencialidade e documentação da assistência. Discute questões éticas e legais da atuação da enfermagem, considerando o respeito ao paciente, a comunicação e os limites de competência no trabalho compartilhado.","summaryOrigin":"editorial"},{"name":"Liderança, Comunicação e Gestão da Equipe no Atendimento Móvel","hours":10,"summary":"Explora liderança, comunicação e organização do trabalho entre os profissionais do atendimento móvel. Discute distribuição de responsabilidades, tomada de decisão compartilhada e manejo de dificuldades na interação da equipe. Relaciona esses temas à passagem de informações, à cooperação sob pressão e à construção de processos que favoreçam a segurança do paciente e dos trabalhadores.","summaryOrigin":"editorial"},{"name":"Simulação Realística e Cenários de Ambulância","hours":10,"summary":"Discute a simulação como recurso de aprendizagem para situações relacionadas ao trabalho em ambulância. Aborda construção e análise de cenários, distribuição de papéis e reflexão sobre as decisões da equipe. Relaciona os acontecimentos simulados à comunicação, à segurança e à identificação de oportunidades de melhoria, sem perder de vista os fundamentos da assistência de enfermagem.","summaryOrigin":"editorial"},{"name":"Metodologia da Pesquisa e Produção Científica","hours":10,"summary":"Apresenta os fundamentos da pesquisa aplicada às questões do atendimento pré-hospitalar. Aborda definição do problema, busca e avaliação de evidências, escolha do método e organização da escrita. Discute como relacionar uma pergunta surgida da prática a um percurso de investigação, com atenção à ética, à qualidade das fontes e à comunicação dos resultados para a área da enfermagem.","summaryOrigin":"editorial"},{"name":"TCC - Trabalho de Conclusão de Curso","hours":10,"summary":"Integra os conhecimentos da especialização na elaboração de um trabalho acadêmico relacionado ao APH. Discute delimitação do tema, construção da pergunta e coerência entre objetivos, método e resultados. Aborda a organização do texto e das referências, permitindo apresentar uma análise fundamentada de questões relevantes para a assistência, a gestão ou a educação em enfermagem.","summaryOrigin":"editorial"}],"sumHours":360,"source":"PPC Pos Graduacao EnfermagemAPH Ambulancia.docx","notes":[],"hasTotalConflict":false},"enfermagem-mulher":{"officialName":"Enfermagem em Saúde da Mulher - Alta Complexidade e Cuidado Integral","declaredHours":360,"components":[{"name":"Políticas Públicas e Linha de Cuidado à Saúde da Mulher","hours":20,"summary":"Analisa as políticas de atenção integral à saúde das mulheres e sua relação com a organização dos serviços. Aborda linhas de cuidado, acesso e articulação entre os níveis de assistência. Discute como a enfermagem pode reconhecer necessidades, acompanhar percursos e contribuir para um cuidado que considere as diferentes fases da vida e as condições sociais das pacientes.","summaryOrigin":"editorial"},{"name":"Anatomia, Fisiologia e Principais Agravos Ginecológicos","hours":20,"summary":"Revisa os fundamentos anatômicos e fisiológicos relacionados à saúde ginecológica e às suas principais alterações. Articula esses conhecimentos à compreensão de sinais, sintomas e necessidades de cuidado. Discute sua importância para a avaliação de enfermagem, para a comunicação com a equipe e para a assistência à mulher em diferentes situações clínicas e momentos da vida.","summaryOrigin":"editorial"},{"name":"Ginecologia de Alta Complexidade","hours":30,"summary":"Explora as condições ginecológicas que demandam acompanhamento de maior complexidade e a organização da assistência de enfermagem nesses contextos. Relaciona avaliação, recursos diagnósticos e necessidades de cuidado. Discute a continuidade do acompanhamento, a comunicação entre profissionais e o acolhimento das repercussões físicas e emocionais vividas pela mulher.","summaryOrigin":"editorial"},{"name":"Assistência à Mulher no Ciclo Gravídico-Puerperal de Alto Risco","hours":30,"summary":"Aborda a assistência de enfermagem à mulher no ciclo gravídico-puerperal de alto risco. Relaciona condições clínicas, acompanhamento especializado e identificação de necessidades à organização do cuidado. Discute comunicação, acolhimento e articulação da rede, considerando a segurança materna, a continuidade da assistência e as experiências da mulher e de sua família.","summaryOrigin":"editorial"},{"name":"Emergências Obstétricas e Ginecológicas","hours":30,"summary":"Examina as situações de urgência e emergência obstétrica e ginecológica sob a perspectiva da enfermagem. Aborda avaliação, identificação de prioridades, comunicação e trabalho em equipe. Relaciona esses temas à preparação do serviço e à continuidade do cuidado, com atenção à segurança, à documentação da assistência e ao acolhimento da mulher em momentos de maior vulnerabilidade.","summaryOrigin":"editorial"},{"name":"Enfermagem em Centro Cirúrgico e Pós-Operatório Ginecológico","hours":20,"summary":"Estuda os cuidados de enfermagem nos períodos que antecedem e sucedem procedimentos ginecológicos e mamários. Aborda preparação, segurança cirúrgica, acompanhamento e prevenção de riscos assistenciais. Discute a comunicação de orientações e a observação das necessidades de recuperação, considerando conforto, autonomia e continuidade do cuidado após a passagem pelo centro cirúrgico.","summaryOrigin":"editorial"},{"name":"Terapia Intensiva e Cuidados à Mulher Criticamente Enferma","hours":30,"summary":"Explora a assistência à mulher em condição crítica e as necessidades de cuidado em terapia intensiva. Relaciona avaliação clínica, monitorização e observação da evolução à organização do trabalho de enfermagem. Discute comunicação com a equipe e com a família, segurança assistencial e atenção às dimensões humanas envolvidas no acompanhamento de pacientes de alta complexidade.","summaryOrigin":"editorial"},{"name":"Oncologia Ginecológica","hours":30,"summary":"Aborda a enfermagem no contexto dos cânceres ginecológicos, articulando prevenção, diagnóstico e acompanhamento. Discute as necessidades de cuidado nas diferentes etapas do percurso oncológico e os efeitos da doença na vida da mulher. Relaciona informações clínicas, acolhimento e trabalho em rede à continuidade da assistência e à participação da paciente nas decisões sobre seu cuidado.","summaryOrigin":"editorial"},{"name":"Câncer de Mama e Assistência à Mulher Oncológica","hours":30,"summary":"Examina o câncer de mama e as necessidades de assistência ao longo do rastreamento, do diagnóstico e do tratamento. Discute avaliação de enfermagem, acolhimento e comunicação de informações. Relaciona o acompanhamento clínico às repercussões na imagem corporal, nas relações e na vida cotidiana, com atenção à autonomia da mulher e à continuidade do cuidado na rede de saúde.","summaryOrigin":"editorial"},{"name":"Tratamento Oncológico, Cirurgia e Reconstrução Mamária","hours":20,"summary":"Estuda os percursos de tratamento oncológico e os cuidados relacionados às cirurgias e à reconstrução mamária. Aborda preparação, acompanhamento e necessidades de recuperação sob a perspectiva da enfermagem. Discute os impactos físicos e emocionais dessas experiências, articulando segurança, orientação e apoio à mulher durante as diferentes etapas de sua assistência.","summaryOrigin":"editorial"},{"name":"Cuidados Paliativos e Manejo de Sintomas","hours":20,"summary":"Apresenta os fundamentos dos cuidados paliativos e sua relação com o conforto e a qualidade de vida da mulher. Aborda avaliação de sintomas, comunicação e identificação das necessidades da paciente e de sua família. Discute a atuação da enfermagem no cuidado compartilhado, considerando autonomia, acolhimento e dimensões físicas, emocionais e sociais do processo de adoecimento.","summaryOrigin":"editorial"},{"name":"Segurança, Qualidade e Humanização no Cuidado à Mulher","hours":20,"summary":"Relaciona segurança do paciente, qualidade assistencial e humanização nos serviços de atenção à mulher. Aborda identificação de riscos, comunicação e organização dos processos de cuidado. Discute a construção de práticas que respeitem a dignidade e as escolhas da paciente, além do uso de registros e da análise de ocorrências para orientar melhorias na assistência de enfermagem.","summaryOrigin":"editorial"},{"name":"Navegação da Paciente e Gestão da Linha de Cuidado","hours":20,"summary":"Explora a navegação da paciente como estratégia de acompanhamento ao longo da linha de cuidado. Analisa barreiras de acesso, transições entre serviços e necessidades de informação. Discute o papel da enfermagem na articulação da rede e no acompanhamento da jornada, considerando continuidade, comunicação e identificação de dificuldades que possam comprometer o seguimento da assistência.","summaryOrigin":"editorial"},{"name":"Pesquisa, Prática Baseada em Evidências e Trabalho Científico","hours":20,"summary":"Relaciona método científico e prática baseada em evidências às questões da saúde da mulher. Aborda formulação de perguntas, busca e avaliação de estudos e organização da produção acadêmica. Discute como transformar problemas da assistência em investigação fundamentada, com atenção à ética, à qualidade das informações e às possibilidades de aplicação do conhecimento no cuidado.","summaryOrigin":"editorial"},{"name":"Gestão do Cuidado e Indicadores Assistenciais","hours":20,"summary":"Examina a gestão do cuidado de enfermagem e o uso de indicadores na atenção à mulher. Relaciona planejamento, registros e avaliação dos processos à identificação de necessidades assistenciais. Discute como interpretar informações sobre o atendimento e orientar melhorias, considerando a organização das equipes, a segurança da paciente e a continuidade do acompanhamento na rede.","summaryOrigin":"editorial"},{"name":"Seminário Integrador e Projeto Aplicado ou TCC","hours":20,"summary":"Articula os temas da especialização por meio de um trabalho integrador relacionado à saúde da mulher. Discute a escolha de um problema, a análise do contexto e a organização de uma proposta fundamentada. Aborda a comunicação dos resultados e a reflexão sobre o percurso desenvolvido, aproximando os conhecimentos do curso das questões da assistência, da gestão ou da pesquisa em enfermagem.","summaryOrigin":"editorial"}],"sumHours":380,"source":"PÓS GRADUAÇÃO EM ENFERMAGEM EM SAÚDE DA MULHER - ALTA COMPLEXIDADE E CUIDADO INTEGRAL.docx","notes":["O documento informa 360 h, mas as 16 disciplinas listadas somam 380 h. As cargas de cada disciplina foram preservadas. O total precisa de confirmação."],"hasTotalConflict":true},"direito-militar":{"officialName":"Direito Militar","declaredHours":360,"components":[{"name":"Direito Constitucional Militar","hours":30,"summary":"Examina os fundamentos constitucionais das instituições militares e sua relação com o Estado e os direitos fundamentais. Aborda organização, competências e particularidades da Justiça Militar. Discute a interpretação das normas e os limites da atuação institucional, articulando hierarquia, disciplina e proteção de garantias na análise de questões do Direito Militar.","summaryOrigin":"editorial"},{"name":"Direito Administrativo Militar","hours":30,"summary":"Estuda o regime jurídico dos militares e os princípios que orientam a Administração Militar. Aborda atos administrativos, deveres, responsabilidades e formas de controle da atuação estatal. Relaciona esses temas à análise de situações funcionais e à fundamentação das decisões, considerando a legalidade, a motivação e o respeito às garantias dos sujeitos envolvidos.","summaryOrigin":"editorial"},{"name":"Direito Administrativo Disciplinar Militar","hours":30,"summary":"Analisa o poder disciplinar e os valores e deveres que estruturam as relações militares. Examina apuração de condutas, produção de provas, defesa e recursos nos procedimentos disciplinares. Discute a relação entre a preservação da disciplina e as garantias processuais, com atenção à motivação das decisões e ao controle da atuação administrativa em cada situação.","summaryOrigin":"editorial"},{"name":"Direito Penal Militar I - Parte Geral e Teoria do Crime Militar","hours":30,"summary":"Apresenta os fundamentos do Direito Penal Militar e os elementos utilizados na análise do crime militar. Aborda princípios, aplicação da lei penal, teoria do delito e consequências jurídicas da conduta. Relaciona esses conteúdos à identificação de questões de tipicidade, responsabilidade e punibilidade, construindo uma base para o estudo dos crimes militares em espécie.","summaryOrigin":"editorial"},{"name":"Direito Penal Militar II - Crimes Militares em Espécie e Legislação Correlata","hours":30,"summary":"Examina os crimes militares em espécie e sua relação com a legislação correlata. Discute a identificação dos elementos das condutas, a interpretação dos tipos penais e os problemas de enquadramento jurídico. Relaciona esses temas às particularidades do contexto militar, à delimitação de competências e à análise fundamentada das circunstâncias presentes em cada caso.","summaryOrigin":"editorial"},{"name":"Processo Penal Militar I - Polícia Judiciária Militar, IPM e Ação Penal Militar","hours":30,"summary":"Estuda a investigação e o início da persecução penal militar, com atenção à Polícia Judiciária Militar e ao inquérito. Aborda organização judiciária, sujeitos processuais e ação penal militar. Discute a finalidade dos atos investigativos, os registros e o encaminhamento das informações, relacionando a apuração dos fatos à preservação das garantias e à estrutura do processo.","summaryOrigin":"editorial"},{"name":"Processo Penal Militar II - Procedimentos, Cautelares, Nulidades e Recursos","hours":30,"summary":"Explora os procedimentos do processo penal militar e as formas de controle dos atos e decisões. Aborda medidas cautelares, nulidades e recursos, distinguindo suas finalidades e pressupostos. Discute a construção dos argumentos processuais e a identificação de questões que podem afetar a regularidade do procedimento, sempre em relação às garantias dos envolvidos.","summaryOrigin":"editorial"},{"name":"Prova e Perícia no Processo Penal Militar","hours":30,"summary":"Analisa a produção e a avaliação da prova no processo penal militar, incluindo os exames periciais. Aborda cadeia de custódia, quesitos, evidências digitais e leitura de laudos. Discute como relacionar os achados técnicos às questões jurídicas, reconhecendo os limites das conclusões periciais e a importância da fundamentação na apresentação e na valoração das informações.","summaryOrigin":"editorial"},{"name":"Prática Penal e Processual Penal Militar","hours":30,"summary":"Relaciona os fundamentos penais e processuais militares à análise da atuação profissional. Aborda organização de argumentos, leitura de elementos probatórios e estruturação de peças e manifestações. Discute audiências e sustentação oral a partir dos papéis processuais e das questões do caso, com atenção à coerência da estratégia, à linguagem e ao respeito às garantias.","summaryOrigin":"editorial"},{"name":"Noções de Direito Previdenciário Militar e Sistema de Proteção Social","hours":30,"summary":"Apresenta noções sobre o Sistema de Proteção Social dos Militares e suas diferenças em relação a outros regimes. Aborda reserva, reforma, pensões e situações relacionadas a dependentes. Discute a leitura dos requisitos e dos vínculos jurídicos envolvidos, permitindo organizar questões e documentos relevantes para o estudo dos direitos e das responsabilidades nessa área.","summaryOrigin":"editorial"},{"name":"Temas Especiais de Direito Militar e Jurisprudência Aplicada","hours":30,"summary":"Examina temas controvertidos e questões de interpretação no campo do Direito Militar. Relaciona legislação, doutrina e jurisprudência à análise de problemas e à construção de argumentos. Discute a leitura crítica de decisões, a identificação de fundamentos e as diferenças entre situações, evitando conclusões genéricas e favorecendo uma avaliação jurídica contextualizada.","summaryOrigin":"editorial"},{"name":"TCC - Artigo Científico","hours":30,"summary":"Orienta a elaboração de um artigo científico sobre uma questão do Direito Militar. Aborda delimitação do tema, problema de pesquisa, seleção de fontes e organização dos argumentos. Discute coerência entre objetivos, desenvolvimento e conclusão, além de escrita acadêmica e referências, para apresentar uma investigação fundamentada e relacionada aos conhecimentos da especialização.","summaryOrigin":"editorial"}],"sumHours":360,"source":"PPC_Especializacao_Direito_Militar_360h_12_Disciplinas.docx","notes":["A capa e a matriz informam 360 h (12 x 30 h). A identificação e um cronograma antigo ainda apresentam 430 h. Foi adotada a matriz curricular de 360 h."],"hasTotalConflict":false},"direito-penal-processo":{"officialName":"Penal e Processo Penal Constitucional - Teoria e Prática","declaredHours":360,"components":[{"name":"Fundamentos Constitucionais do Direito Penal e Processual Penal","hours":30,"summary":"Relaciona o Direito Penal e o Processo Penal aos fundamentos da Constituição e aos limites do poder punitivo. Aborda princípios, proteção de direitos e critérios de interpretação das normas. Discute como essas referências orientam a análise de condutas, procedimentos e decisões, construindo uma base para compreender as garantias que atravessam a persecução penal.","summaryOrigin":"editorial"},{"name":"Teoria Geral do Processo Penal e Sistema Acusatório","hours":30,"summary":"Examina a estrutura do processo penal e os fundamentos do sistema acusatório. Aborda funções dos sujeitos processuais, jurisdição, ação e distribuição de responsabilidades na persecução penal. Discute a relação entre imparcialidade, contraditório e produção da prova, permitindo compreender como a organização do procedimento se conecta à legitimidade das decisões.","summaryOrigin":"editorial"},{"name":"Garantias Fundamentais e Devido Processo Legal Penal","hours":30,"summary":"Analisa as garantias fundamentais aplicáveis à investigação e ao processo penal. Relaciona devido processo legal, defesa, contraditório e presunção de inocência à avaliação dos atos estatais. Discute os efeitos dessas garantias na produção de provas, na fundamentação das decisões e no controle de restrições de direitos, considerando as circunstâncias de cada situação.","summaryOrigin":"editorial"},{"name":"Criminologia, Política Criminal e Sistema Punitivo","hours":30,"summary":"Estuda as relações entre criminologia, política criminal e organização do sistema punitivo. Aborda explicações sobre a criminalidade, processos de criminalização e respostas institucionais ao conflito. Discute como fatores sociais e escolhas públicas influenciam a atuação do sistema de justiça, favorecendo uma leitura crítica de seus objetivos, limites e efeitos sobre diferentes grupos.","summaryOrigin":"editorial"},{"name":"Investigação Criminal, Polícia Judiciária e Garantias Constitucionais","hours":30,"summary":"Examina a investigação criminal e a atuação da polícia judiciária na apuração dos fatos. Relaciona finalidade, limites e documentação dos atos investigativos às garantias constitucionais. Discute obtenção de informações, controle da legalidade e participação dos sujeitos envolvidos, permitindo analisar a fase investigativa sem afastá-la dos direitos e das exigências do processo penal.","summaryOrigin":"editorial"},{"name":"Teoria Geral da Prova e Cadeia de Custódia","hours":30,"summary":"Apresenta os fundamentos da prova penal e os critérios utilizados em sua produção e avaliação. Aborda fontes de prova, preservação de vestígios e cadeia de custódia. Discute a relação entre confiabilidade, contraditório e fundamentação, permitindo examinar o percurso das evidências e os limites de sua utilização na construção de conclusões sobre os fatos investigados.","summaryOrigin":"editorial"},{"name":"Medidas Cautelares Pessoais e Reais no Processo Penal","hours":30,"summary":"Estuda as medidas cautelares pessoais e patrimoniais no processo penal, distinguindo suas finalidades e pressupostos. Relaciona necessidade, adequação e proporcionalidade ao exame de restrições impostas durante a persecução. Discute a fundamentação das decisões, as possibilidades de controle e a avaliação dos efeitos de cada medida sobre os direitos dos envolvidos.","summaryOrigin":"editorial"},{"name":"Prisões, Audiência de Custódia e Medidas de Concessões de Liberdades","hours":30,"summary":"Analisa as modalidades de prisão e as questões relacionadas à audiência de custódia e à liberdade no processo penal. Discute os fundamentos das decisões e a avaliação das condições do caso. Relaciona controle da legalidade, proteção da integridade e medidas alternativas à compreensão das garantias, evitando tratar a restrição da liberdade como consequência automática da investigação.","summaryOrigin":"editorial"},{"name":"Inquérito Policial, Audiência de Custódia e Proposta de ANPP - Teoria e Prática","hours":30,"summary":"Articula a investigação policial, a audiência de custódia e o estudo do acordo de não persecução penal. Examina documentos, argumentos e questões que surgem na fase anterior ao processo. Discute a organização de informações e a atuação dos sujeitos envolvidos, relacionando as possibilidades de solução do caso aos requisitos jurídicos e às garantias que orientam cada procedimento.","summaryOrigin":"editorial"},{"name":"Procedimentos Penais Comuns e Especiais - Teoria e Prática","hours":30,"summary":"Examina os procedimentos penais comuns e especiais, suas etapas e finalidades. Relaciona a organização dos atos à participação das partes, à produção da prova e à formação da decisão. Discute como identificar o caminho processual adequado e analisar questões surgidas em cada fase, com atenção à fundamentação dos pedidos e ao controle da regularidade do procedimento.","summaryOrigin":"editorial"},{"name":"Tribunal do Júri e Procedimento dos Crimes Dolosos Contra a Vida - Teoria e Prática","hours":30,"summary":"Estuda a organização e a competência do Tribunal do Júri no julgamento dos crimes dolosos contra a vida. Aborda as fases do procedimento, a preparação do plenário e a atuação dos sujeitos processuais. Discute a relação entre prova, narrativa e garantias, permitindo compreender as particularidades da decisão dos jurados e os limites jurídicos que orientam o julgamento.","summaryOrigin":"editorial"},{"name":"Recursos, Impugnações e Controle da Decisão Penal - Teoria e Prática","hours":30,"summary":"Aborda o sistema de recursos e os demais meios de impugnação das decisões penais. Examina pressupostos, efeitos e finalidades de cada instrumento, relacionando-os ao tipo de decisão e à questão discutida. Discute a organização dos fundamentos e o controle de erros processuais ou de julgamento, articulando segurança jurídica, defesa e revisão das conclusões adotadas.","summaryOrigin":"editorial"},{"name":"Execução Penal, Justiça Penal Negociada e Soluções Consensuais - Teoria e Prática","hours":30,"summary":"Relaciona execução penal, justiça negociada e formas consensuais de resposta ao conflito criminal. Examina finalidades, sujeitos e garantias presentes nesses diferentes momentos e instrumentos. Discute condições de aplicação, acompanhamento e controle, permitindo distinguir as exigências da execução da pena das questões envolvidas na construção e na avaliação de acordos penais.","summaryOrigin":"editorial"}],"sumHours":390,"source":"PROJETO POS FBE WORD FIM.docx","notes":["O documento declara 360 h, mas a matriz lista 13 disciplinas de 30 h, somando 390 h. As 13 disciplinas e suas cargas foram mantidas. O total precisa de confirmação."],"hasTotalConflict":true},"direitos-mulheres":{"officialName":"Direitos Humanos das Mulheres e Justiça de Gênero","declaredHours":360,"components":[{"name":"Direitos Humanos das Mulheres: Teoria, História e Marcos Normativos","hours":30,"summary":"Apresenta a formação histórica dos direitos humanos das mulheres e os principais marcos de proteção. Discute tensões entre universalidade, diferenças e condições concretas de acesso a direitos. Relaciona esses fundamentos à leitura de problemas jurídicos e institucionais, reconhecendo como desigualdades de gênero atravessam a definição de demandas e a construção de respostas.","summaryOrigin":"editorial"},{"name":"Teoria Feminista e Crítica ao Direito","hours":15,"summary":"Explora matrizes do pensamento feminista e suas contribuições para a crítica ao Direito. Aborda patriarcado, divisão sexual do trabalho e construção social das desigualdades. Discute como normas, instituições e interpretações podem reproduzir ou enfrentar essas relações, ampliando as referências utilizadas na análise de conflitos e no reconhecimento dos direitos das mulheres.","summaryOrigin":"editorial"},{"name":"Feminismo Negro, Racismo Institucional e Direito","hours":30,"summary":"Relaciona o pensamento feminista negro à análise do racismo institucional e das desigualdades jurídicas. Aborda a interseccionalidade como perspectiva para compreender experiências atravessadas por raça, gênero e classe. Discute seus efeitos no acesso à justiça e nas respostas institucionais, evitando tratar as mulheres como um grupo homogêneo na formulação de ações e argumentos.","summaryOrigin":"editorial"},{"name":"Mulheres em Contextos Plurais e Territórios","hours":20,"summary":"Examina a diversidade de experiências das mulheres em diferentes territórios e contextos sociais. Relaciona gênero, pertencimento e condições de vida às barreiras no acesso a direitos e serviços. Discute a atenção às especificidades de comunidades e grupos, reconhecendo a importância da escuta e da leitura do contexto para a construção de respostas jurídicas e institucionais adequadas.","summaryOrigin":"editorial"},{"name":"Violência Doméstica e Familiar e Feminicídio","hours":35,"summary":"Estuda as relações entre violência doméstica e familiar, proteção de direitos e feminicídio. Aborda formas de violência, dinâmicas de risco e instrumentos de proteção apresentados no curso. Discute a articulação entre sistema de justiça e rede de atendimento, com atenção à análise do contexto, à prevenção da revitimização e às necessidades das mulheres envolvidas.","summaryOrigin":"editorial"},{"name":"Violência de Gênero na Era Digital e Prova Digital","hours":30,"summary":"Analisa formas de violência de gênero mediadas por tecnologias e redes digitais. Aborda circulação de conteúdos, exposição, perseguição e questões relacionadas à obtenção e à preservação de provas. Discute a relação entre proteção da vítima, segurança das informações e resposta jurídica, considerando as particularidades do ambiente digital e os limites da interpretação dos registros.","summaryOrigin":"editorial"},{"name":"Violência Institucional, Obstétrica e Política","hours":20,"summary":"Examina a violência institucional e suas manifestações em serviços, relações políticas e contextos de atenção obstétrica. Relaciona práticas de discriminação e revitimização às condições de exercício dos direitos das mulheres. Discute acolhimento, responsabilização e mudanças institucionais, considerando a escuta das experiências e a análise dos processos que permitem a continuidade dessas violências.","summaryOrigin":"editorial"},{"name":"Direito das Famílias e Direitos das Mulheres","hours":35,"summary":"Estuda questões do Direito das Famílias a partir dos direitos e das experiências das mulheres. Aborda vínculos familiares, relações patrimoniais e responsabilidades de cuidado. Discute como desigualdades e situações de violência podem atravessar os conflitos, relacionando interpretação jurídica, proteção e autonomia à análise das necessidades concretas dos sujeitos envolvidos.","summaryOrigin":"editorial"},{"name":"Trabalho, Economia do Cuidado e Autonomia Econômica","hours":20,"summary":"Relaciona trabalho, economia do cuidado e autonomia econômica às desigualdades de gênero. Aborda divisão de responsabilidades, trabalho doméstico e barreiras no acesso a renda e oportunidades. Discute a articulação entre proteção jurídica e políticas públicas, permitindo reconhecer como o cuidado e as condições materiais influenciam o exercício dos direitos e a participação social das mulheres.","summaryOrigin":"editorial"},{"name":"Saúde, Direitos Sexuais e Reprodutivos e Justiça Reprodutiva","hours":15,"summary":"Apresenta os direitos sexuais e reprodutivos como parte do debate sobre direitos humanos e saúde das mulheres. Relaciona autonomia, acesso a serviços e desigualdades sociais à perspectiva da justiça reprodutiva. Discute a leitura de conflitos e de respostas institucionais com atenção à dignidade, à informação e à diversidade de experiências envolvidas nas decisões sobre o próprio corpo.","summaryOrigin":"editorial"},{"name":"Justiça de Gênero e Julgamento com Perspectiva de Gênero","hours":20,"summary":"Examina o acesso à justiça e a análise de conflitos com perspectiva de gênero. Discute estereótipos, desigualdades e critérios de interpretação que podem influenciar a apreciação dos fatos e das provas. Relaciona essas questões à fundamentação das decisões e ao reconhecimento das experiências das mulheres, favorecendo uma leitura contextualizada das situações submetidas ao sistema de justiça.","summaryOrigin":"editorial"},{"name":"Sistema Interamericano, Litigância Estratégica e Direitos Humanos das Mulheres","hours":20,"summary":"Aborda os sistemas internacionais de proteção e as possibilidades de atuação estratégica em direitos humanos das mulheres. Examina a organização de demandas, a leitura de decisões e a construção de argumentos. Discute a relação entre situações individuais e problemas estruturais, considerando os caminhos institucionais, a seleção de informações e os objetivos de proteção envolvidos na atuação.","summaryOrigin":"editorial"},{"name":"Redes de Enfrentamento e Políticas Públicas","hours":10,"summary":"Estuda a organização das redes de enfrentamento à violência contra as mulheres e sua relação com as políticas públicas. Aborda serviços, responsabilidades e articulação entre diferentes setores. Discute fluxos de atendimento, comunicação e continuidade do acompanhamento, com atenção às barreiras de acesso e à construção de respostas que considerem o contexto e as necessidades de cada mulher.","summaryOrigin":"editorial"},{"name":"Tópicos Especiais","hours":10,"summary":"Discute questões emergentes no campo dos direitos humanos das mulheres e da justiça de gênero. Relaciona problemas contemporâneos às referências teóricas, aos marcos de proteção e às respostas institucionais. Examina diferentes argumentos e possibilidades de análise, favorecendo a atualização do debate sem perder de vista os contextos sociais e as garantias dos sujeitos envolvidos.","summaryOrigin":"editorial"},{"name":"Seminário Integrador","hours":5,"summary":"Integra os temas do curso por meio da análise e da comunicação de questões relacionadas aos direitos das mulheres. Discute a organização de estudos de caso, projetos e produções acadêmicas. Relaciona diferentes perspectivas à construção de argumentos e à reflexão sobre os resultados, permitindo aproximar os conhecimentos da especialização dos problemas encontrados em contextos profissionais.","summaryOrigin":"editorial"},{"name":"Planejamento e Desenvolvimento de Carreira Profissional","hours":5,"summary":"Relaciona a trajetória profissional aos conhecimentos e aos campos de atuação abordados na especialização. Discute identificação de interesses, reconhecimento de competências e definição de objetivos de desenvolvimento. Examina possibilidades de organização da carreira, de colaboração e de formação continuada, considerando o compromisso com os direitos das mulheres e a análise do contexto de atuação.","summaryOrigin":"editorial"},{"name":"Produção Científica I","hours":20,"summary":"Apresenta os fundamentos da investigação científica aplicada aos direitos humanos das mulheres e à justiça de gênero. Aborda problema de pesquisa, seleção de fontes e escolha de métodos. Discute a relação entre evidências, interpretação e escrita acadêmica, com atenção à ética e à coerência dos argumentos na construção de um trabalho relacionado às questões da especialização.","summaryOrigin":"editorial"},{"name":"Produção Científica II - TCC","hours":20,"summary":"Articula o desenvolvimento da pesquisa à elaboração e à comunicação do trabalho final. Aborda estrutura do texto, organização dos argumentos, apresentação dos resultados e referências. Discute a consistência entre pergunta, percurso metodológico e conclusão, permitindo explicitar a contribuição do estudo para a compreensão ou o enfrentamento de problemas relativos aos direitos das mulheres.","summaryOrigin":"editorial"}],"sumHours":360,"source":"PPC - Especialização em Direitos Humanos das Mulheres e Justiça de Gênero.pdf","notes":[],"hasTotalConflict":false},"seguranca-publica":{"officialName":"Segurança Pública e Política Criminal","declaredHours":360,"components":[{"name":"Teoria do Estado, Democracia e Representação Política","hours":20,"summary":"Estuda a formação do Estado e as relações entre poder, legitimidade e representação política. Aborda democracia, soberania e organização institucional como referências para o campo da segurança pública. Discute como essas bases se conectam ao exercício da autoridade e à participação social, permitindo analisar os limites e as responsabilidades do Estado na gestão dos conflitos.","summaryOrigin":"editorial"},{"name":"Constituição, Direitos Fundamentais e Sistema de Segurança Pública","hours":20,"summary":"Relaciona a segurança pública aos fundamentos constitucionais e à proteção dos direitos fundamentais. Aborda organização do sistema, responsabilidades institucionais e garantias dos sujeitos envolvidos. Discute os limites da atuação estatal e a necessidade de articulação entre órgãos, permitindo compreender a segurança como uma questão que envolve legalidade, cidadania e controle público.","summaryOrigin":"editorial"},{"name":"Interdisciplinaridade, Métodos de Pesquisa e Diagnóstico Criminal","hours":20,"summary":"Apresenta formas de produção de conhecimento sobre violência, criminalidade e atuação institucional. Aborda definição de problemas, escolha de métodos e interpretação de informações. Discute a construção de diagnósticos que articulem diferentes áreas de estudo e fontes de evidência, considerando limites dos dados e sua utilidade no planejamento e na avaliação de ações de segurança pública.","summaryOrigin":"editorial"},{"name":"Sociologia da Violência e Criminologia","hours":20,"summary":"Explora abordagens sociológicas e criminológicas para compreender violência, conflito e controle social. Examina explicações sobre criminalidade, construção do desvio e respostas das instituições. Relaciona essas perspectivas aos contextos e às desigualdades sociais, favorecendo uma análise crítica dos problemas de segurança e dos efeitos das intervenções sobre diferentes grupos e territórios.","summaryOrigin":"editorial"},{"name":"Políticas Públicas, Gestão Estratégica e Governança da Segurança","hours":20,"summary":"Examina a formulação e a gestão de políticas públicas no campo da segurança. Aborda formação de agenda, definição de prioridades, planejamento e articulação entre instituições. Discute a relação entre objetivos, recursos e acompanhamento dos resultados, permitindo analisar a coerência das ações e as responsabilidades envolvidas na governança e na prestação de contas à sociedade.","summaryOrigin":"editorial"},{"name":"Política Criminal, Vitimologia e Direitos Humanos","hours":20,"summary":"Relaciona as escolhas de política criminal à proteção das vítimas e aos direitos humanos. Aborda processos de criminalização, necessidades de atendimento e efeitos das respostas punitivas. Discute como diferentes decisões públicas podem ampliar ou reduzir vulnerabilidades, considerando prevenção, responsabilização e garantias na avaliação das estratégias de enfrentamento dos conflitos.","summaryOrigin":"editorial"},{"name":"Direito Penal I: Teoria do Crime, Pena e Limites do Poder Punitivo","hours":20,"summary":"Apresenta os fundamentos da teoria do crime e da pena, relacionando-os aos limites constitucionais da punição. Aborda aplicação da lei penal e critérios de responsabilização. Discute a análise da conduta e de suas consequências jurídicas, construindo uma base para compreender como a proteção de bens jurídicos deve ser articulada às garantias e ao controle do poder punitivo.","summaryOrigin":"editorial"},{"name":"Direito Penal II: Crimes em Espécie e Problemas Contemporâneos","hours":20,"summary":"Examina grupos de crimes e problemas de interpretação que surgem na análise de situações concretas. Relaciona os elementos das condutas à proteção de bens jurídicos e às formas de responsabilização. Discute conflitos de enquadramento e questões contemporâneas, com atenção à fundamentação dos argumentos e à diferença entre o estudo jurídico dos fatos e sua percepção no debate público.","summaryOrigin":"editorial"},{"name":"Processo Penal I: Investigação, Ação Penal e Medidas Cautelares","hours":20,"summary":"Estuda a investigação, a ação penal e as medidas cautelares como partes da persecução criminal. Aborda os sujeitos envolvidos, as finalidades dos atos e os critérios de controle de sua legalidade. Relaciona organização do procedimento, fundamentação e proteção de garantias à análise da atuação das instituições de segurança e de justiça nos diferentes momentos do caso.","summaryOrigin":"editorial"},{"name":"Processo Penal II: Prova, Cadeia de Custódia, Nulidades e Decisão","hours":20,"summary":"Analisa a produção da prova e a formação da decisão no processo penal. Aborda preservação de vestígios, cadeia de custódia, nulidades e exigências de fundamentação. Discute confiabilidade das informações e limites das conclusões, permitindo compreender a relação entre os procedimentos adotados, os direitos das partes e a qualidade dos argumentos utilizados no julgamento.","summaryOrigin":"editorial"},{"name":"Leis Penais Extravagantes I: Criminalidade Organizada e Delitos de Alta Complexidade","hours":20,"summary":"Examina a legislação penal especial relacionada à criminalidade organizada e a delitos de maior complexidade. Aborda problemas de interpretação, investigação e articulação institucional presentes nesses contextos. Discute a relação entre respostas especializadas e proteção de garantias, considerando os limites da atuação estatal e a necessidade de fundamentar a análise de cada situação.","summaryOrigin":"editorial"},{"name":"Leis Penais Extravagantes II: Proteção de Vulneráveis e Novas Formas de Violência","hours":20,"summary":"Estuda a proteção jurídica de grupos em situação de vulnerabilidade e as respostas a formas de violência tratadas pela legislação especial. Relaciona os contextos das vítimas às necessidades de investigação e atendimento. Discute a articulação entre prevenção, proteção e responsabilização, com atenção ao risco de revitimização e à adequação da atuação institucional diante de diferentes demandas.","summaryOrigin":"editorial"},{"name":"Execução Penal, Sistema Prisional e Alternativas Penais","hours":20,"summary":"Explora a organização da execução penal e os problemas do sistema prisional. Aborda direitos, deveres, responsabilidades institucionais e possibilidades de alternativas penais. Discute as finalidades da resposta estatal e as condições de acompanhamento, relacionando legalidade, proteção de direitos e integração de políticas na análise dos percursos de cumprimento da pena.","summaryOrigin":"editorial"},{"name":"Inteligência, Tecnologia, Dados e Produção de Conhecimento","hours":20,"summary":"Relaciona inteligência e análise de dados à produção de conhecimento para a segurança pública. Aborda organização de informações, leitura de padrões e comunicação de resultados. Discute a qualidade das fontes, os limites das interpretações e os cuidados com os dados, permitindo avaliar como a tecnologia pode apoiar decisões sem substituir a análise crítica e a responsabilidade institucional.","summaryOrigin":"editorial"},{"name":"Políticas Sociais, Território e Prevenção da Violência","hours":20,"summary":"Analisa a prevenção da violência em diálogo com políticas sociais e características dos territórios. Aborda fatores de risco e proteção, condições de acesso a serviços e articulação de iniciativas locais. Discute a construção de ações contextualizadas e formas de acompanhamento, considerando a participação dos sujeitos e as relações entre segurança, direitos e condições de vida.","summaryOrigin":"editorial"},{"name":"Democracia, Mídia, Participação Popular e Formação da Agenda Penal","hours":20,"summary":"Examina as relações entre mídia, participação social e definição das prioridades da política criminal. Aborda circulação de informações, representação política e formação da opinião pública. Discute como demandas e narrativas chegam às instituições e influenciam decisões, permitindo avaliar a qualidade do debate e a relação entre respostas legislativas, evidências e expectativas sociais.","summaryOrigin":"editorial"},{"name":"Marcos Fáticos da Legislação Penal Brasileira e Resposta Legislativa","hours":20,"summary":"Estuda a relação entre acontecimentos de repercussão pública e a construção de respostas na legislação penal brasileira. Analisa os contextos, os argumentos e os objetivos apresentados no debate legislativo. Discute a diferença entre reação imediata e avaliação de efeitos, permitindo examinar como demandas de segurança se transformam em propostas e escolhas de política criminal.","summaryOrigin":"editorial"},{"name":"Laboratório Integrador de Gestão Estratégica em Segurança Pública e Política Criminal","hours":20,"summary":"Integra os conhecimentos da especialização na análise de um problema de segurança pública ou política criminal. Aborda diagnóstico, definição de objetivos e organização de uma proposta de atuação. Discute a coerência entre evidências, ações e acompanhamento de resultados, permitindo articular diferentes perspectivas na construção de soluções contextualizadas e na comunicação do trabalho desenvolvido.","summaryOrigin":"editorial"}],"sumHours":360,"source":"PPC_Euder_Nascimento.pdf","notes":[],"hasTotalConflict":false},"gestao-estrategica":{"officialName":"Gestão Estratégica das Políticas para Mulheres","declaredHours":360,"components":[{"name":"Gênero, Direitos Humanos e Institucionalidade das Políticas para Mulheres","hours":30,"summary":"Relaciona gênero e direitos humanos à construção das políticas públicas para mulheres. Aborda reconhecimento de demandas, responsabilidades do Estado e organização dos espaços institucionais de atuação. Discute como desigualdades podem ser consideradas na definição de prioridades e na formulação de respostas, aproximando os fundamentos da área dos desafios encontrados na gestão pública.","summaryOrigin":"editorial"},{"name":"Estado, Federalismo e Governança das Políticas para Mulheres","hours":30,"summary":"Examina a organização do Estado e a distribuição de responsabilidades entre os entes federativos nas políticas para mulheres. Aborda coordenação, cooperação e relações entre instituições. Discute como atribuições e arranjos de governança influenciam a implementação das ações, a articulação dos serviços e a continuidade das iniciativas em diferentes contextos territoriais.","summaryOrigin":"editorial"},{"name":"Planejamento Estratégico, Programas, Projetos e Orçamento Responsivo a Gênero","hours":30,"summary":"Apresenta fundamentos do planejamento de políticas, programas e projetos com atenção às desigualdades de gênero. Relaciona definição de prioridades, objetivos e ações às escolhas de alocação de recursos. Discute a articulação entre planejamento e orçamento, permitindo avaliar a coerência das propostas e a presença das necessidades das mulheres nas decisões sobre os investimentos públicos.","summaryOrigin":"editorial"},{"name":"Dados, Indicadores, Estatísticas de Gênero e Diagnóstico Territorial","hours":30,"summary":"Aborda a utilização de dados e indicadores para compreender desigualdades de gênero e necessidades dos territórios. Discute seleção de fontes, qualidade das informações e interpretação dos resultados. Relaciona o diagnóstico à definição de prioridades e ao planejamento das ações, com atenção aos limites dos registros e às diferenças entre os grupos e contextos analisados.","summaryOrigin":"editorial"},{"name":"Monitoramento, Avaliação e Gestão por Resultados","hours":30,"summary":"Examina formas de acompanhar e avaliar políticas e serviços direcionados às mulheres. Aborda objetivos, indicadores, registros e interpretação de resultados ao longo da implementação. Discute a diferença entre atividades realizadas e mudanças alcançadas, permitindo organizar informações que apoiem a revisão das ações, a prestação de contas e o aperfeiçoamento da gestão pública.","summaryOrigin":"editorial"},{"name":"Governança Intersetorial, Redes de Atendimento e Proteção","hours":30,"summary":"Estuda a articulação entre setores e instituições que compõem as redes de atendimento e proteção às mulheres. Aborda responsabilidades, comunicação e pactuação de fluxos de trabalho. Discute os desafios da coordenação e da continuidade do acompanhamento, considerando barreiras de acesso e a necessidade de respostas que integrem as diferentes demandas apresentadas pelas usuárias.","summaryOrigin":"editorial"},{"name":"Design de Serviços, Fluxos, Protocolos e Devolutividade","hours":30,"summary":"Relaciona o desenho de serviços públicos à experiência das mulheres durante o atendimento. Examina percursos, pontos de contato, fluxos e protocolos, com atenção à comunicação e às devolutivas. Discute como identificar dificuldades e organizar propostas de melhoria, articulando a perspectiva das usuárias às responsabilidades das equipes e à capacidade de funcionamento dos serviços.","summaryOrigin":"editorial"},{"name":"Avaliação de Risco e Prevenção ao Feminicídio","hours":30,"summary":"Analisa fatores e contextos relacionados ao risco de violência contra as mulheres e à prevenção do feminicídio. Aborda organização de informações, avaliação das situações e articulação de respostas na rede. Discute a importância do acompanhamento e da comunicação entre serviços, considerando a proteção das mulheres e os limites de interpretações baseadas em registros isolados.","summaryOrigin":"editorial"},{"name":"Tecnologia, Inteligência Artificial e Inovação em Serviços Públicos para Mulheres","hours":30,"summary":"Explora possibilidades e limites do uso de tecnologia e inteligência artificial em serviços públicos para mulheres. Aborda qualidade dos dados, privacidade, acessibilidade e avaliação das soluções. Discute como relacionar inovação às necessidades das usuárias, com atenção a desigualdades, vieses e responsabilidade humana nas decisões e na organização dos processos de atendimento.","summaryOrigin":"editorial"},{"name":"Autonomia Econômica, Trabalho, Cuidado e Desenvolvimento","hours":30,"summary":"Relaciona autonomia econômica, trabalho e responsabilidades de cuidado às condições de vida das mulheres. Aborda barreiras no acesso a renda, oportunidades e serviços de apoio. Discute o planejamento de iniciativas que articulem proteção social e desenvolvimento, considerando as diferenças entre os territórios e a importância de reconhecer o cuidado na formulação das políticas públicas.","summaryOrigin":"editorial"},{"name":"Comunicação Pública, Liderança e Articulação Institucional","hours":30,"summary":"Examina comunicação pública, liderança e articulação institucional na gestão de políticas para mulheres. Aborda construção de mensagens, diálogo com diferentes públicos e organização do trabalho coletivo. Discute como comunicar ações e resultados com clareza, construir cooperação e sustentar a participação, relacionando essas práticas às responsabilidades e aos objetivos do serviço público.","summaryOrigin":"editorial"},{"name":"Policy Lab: Laboratório de Soluções, Produção Científica e Produto Técnico-Profissional","hours":30,"summary":"Integra os conhecimentos do curso na construção de uma proposta de solução para uma questão das políticas para mulheres. Aborda diagnóstico, definição do problema e desenvolvimento de um produto técnico-profissional. Discute a organização das evidências e a comunicação dos resultados, relacionando a produção científica aos desafios da gestão e à avaliação da proposta no contexto de aplicação.","summaryOrigin":"editorial"}],"sumHours":360,"source":"especialização em gestão estratégica.pdf","notes":[],"hasTotalConflict":false},"perspectiva-genero":{"officialName":"Perspectiva de Gênero e Novas Fronteiras do Direito","declaredHours":360,"components":[{"name":"Fundamentos de Gênero, Direitos Humanos e Sistemas de Proteção","hours":30,"summary":"Apresenta fundamentos de gênero e suas relações com os direitos humanos e os sistemas de proteção. Aborda desigualdades, discriminação e condições de acesso a direitos. Discute a leitura de conflitos e respostas institucionais a partir dessas referências, construindo uma base para reconhecer como experiências distintas das mulheres precisam ser consideradas na análise jurídica.","summaryOrigin":"editorial"},{"name":"Lei Maria da Penha, Medidas Protetivas e Avaliação de Risco","hours":30,"summary":"Estuda a proteção diante da violência doméstica e familiar, com atenção à Lei Maria da Penha e às medidas protetivas. Relaciona as formas de violência e os contextos de risco à avaliação das necessidades da mulher. Discute a organização dos argumentos e das informações, além da articulação com a rede de atendimento, sem reduzir a análise às características de um episódio isolado.","summaryOrigin":"editorial"},{"name":"Feminicídio, Violência Vicária e Tribunal do Júri","hours":30,"summary":"Relaciona feminicídio, violência dirigida a pessoas próximas da mulher e atuação no Tribunal do Júri. Examina contexto, relações entre os envolvidos e questões de interpretação dos fatos e das provas. Discute a construção de argumentos que reconheçam as dinâmicas da violência de gênero e as garantias do julgamento, evitando estereótipos na apresentação e na apreciação do caso.","summaryOrigin":"editorial"},{"name":"Crimes Sexuais, Stalking, Violência Psicológica e Outras Violências de Gênero","hours":30,"summary":"Examina crimes sexuais, perseguição e violência psicológica em diálogo com outras manifestações da violência de gênero. Aborda as particularidades dos contextos e os desafios para identificar e demonstrar os fatos. Discute acolhimento, obtenção de informações e construção da resposta jurídica, considerando a proteção dos direitos e os cuidados para não reproduzir a revitimização.","summaryOrigin":"editorial"},{"name":"Processo, Prova e Julgamento com Perspectiva de Gênero","hours":30,"summary":"Analisa procedimentos, provas e decisões judiciais a partir da perspectiva de gênero. Discute como estereótipos e desigualdades podem influenciar a compreensão dos relatos e a avaliação das evidências. Relaciona a leitura do contexto à fundamentação dos argumentos e das decisões, com atenção ao contraditório, à proteção de direitos e à análise individualizada das situações.","summaryOrigin":"editorial"},{"name":"Prova Digital, Cadeia de Custódia, Inteligência Artificial e Violência Digital","hours":30,"summary":"Explora questões da prova digital e da preservação de registros em situações de violência de gênero. Aborda cadeia de custódia, circulação de conteúdos e desafios relacionados à inteligência artificial. Discute confiabilidade, privacidade e limites de interpretação, permitindo relacionar os aspectos técnicos dos materiais à construção de argumentos e à proteção dos sujeitos envolvidos.","summaryOrigin":"editorial"},{"name":"Direito das Famílias, Parentalidade, Violência Patrimonial e Econômica","hours":30,"summary":"Relaciona conflitos familiares, parentalidade e relações patrimoniais às desigualdades e à violência de gênero. Aborda responsabilidades de cuidado, autonomia e questões econômicas presentes nas relações. Discute a análise dos fatos e das necessidades dos envolvidos, com atenção às situações em que decisões sobre família e patrimônio podem afetar a proteção e o exercício dos direitos das mulheres.","summaryOrigin":"editorial"},{"name":"Mulheres, Trabalho, Assédio, Discriminação e Compliance","hours":30,"summary":"Examina as experiências das mulheres no trabalho e os problemas relacionados a assédio e discriminação. Relaciona prevenção, resposta institucional e práticas de compliance à proteção de direitos. Discute o reconhecimento das condutas, a organização dos procedimentos e a comunicação, considerando os contextos das relações profissionais e os cuidados necessários na análise de cada situação.","summaryOrigin":"editorial"},{"name":"Direitos Políticos, Violência Política de Gênero e Participação","hours":30,"summary":"Estuda a participação das mulheres na vida política e as barreiras ao exercício dos direitos políticos. Aborda manifestações de violência e discriminação relacionadas ao gênero em espaços de representação e decisão. Discute formas de análise e de resposta institucional, reconhecendo a relação entre proteção de direitos, pluralidade e condições de participação democrática.","summaryOrigin":"editorial"},{"name":"Advocacia Estratégica, Litigância e Prática Profissional","hours":30,"summary":"Relaciona os conhecimentos da especialização à organização da atuação jurídica em questões de gênero. Aborda definição de objetivos, seleção de informações, construção de argumentos e escolha de caminhos institucionais. Discute estratégias de litigância e comunicação que considerem o contexto e as necessidades das mulheres, com atenção à ética e à consistência dos fundamentos apresentados.","summaryOrigin":"editorial"},{"name":"Rede de Proteção, Políticas Públicas e Prevenção ao Feminicídio","hours":30,"summary":"Examina a articulação entre rede de proteção, políticas públicas e prevenção do feminicídio. Aborda atribuições dos serviços, fluxos de encaminhamento e continuidade do acompanhamento. Discute como informações e responsabilidades podem ser organizadas para enfrentar barreiras de atendimento, considerando o contexto de risco, a proteção dos direitos e a integração das respostas institucionais.","summaryOrigin":"editorial"},{"name":"Temas Contemporâneos, Produção Científica e Produto Técnico-Jurídico","hours":30,"summary":"Articula questões contemporâneas de gênero e Direito à elaboração de uma produção acadêmica ou técnico-jurídica. Aborda delimitação do problema, seleção de fontes e organização dos argumentos. Discute a consistência da proposta e a comunicação de seus resultados, aproximando o estudo dos temas emergentes das necessidades encontradas nos contextos de atuação profissional.","summaryOrigin":"editorial"}],"sumHours":360,"source":"especialização pespectiva de genero.pdf","notes":[],"hasTotalConflict":false},"tribunal-juri-custodia":{"officialName":"Tribunal do Júri e Audiência de Custódia","declaredHours":360,"components":[{"name":"Noções Básicas de Direito Penal e Criminologia Aplicada","hours":25,"summary":"Apresenta conceitos de Direito Penal e criminologia que ajudam a compreender a atuação nos casos submetidos ao júri. Relaciona crime, responsabilização e respostas do sistema de justiça às interpretações sobre a criminalidade. Discute a diferença entre análise jurídica e explicações sociais dos fatos, construindo uma base para o estudo dos procedimentos e de suas garantias.","summaryOrigin":"editorial"},{"name":"Audiência de Custódia e Atuação em Central de Flagrantes","hours":25,"summary":"Examina a audiência de custódia e as questões jurídicas presentes no atendimento em central de flagrantes. Aborda análise de registros, controle da legalidade da prisão e proteção da integridade da pessoa apresentada. Discute a organização de informações e argumentos pelos profissionais envolvidos, relacionando a atuação inicial às garantias e às decisões sobre a continuidade da custódia.","summaryOrigin":"editorial"},{"name":"Homicídio e Provas Periciais; Desclassificação no Plenário","hours":25,"summary":"Relaciona o estudo do homicídio à análise das provas periciais e às questões de desclassificação discutidas em plenário. Aborda interpretação de laudos, limites das conclusões técnicas e relação entre prova e enquadramento jurídico. Discute como organizar os argumentos a partir dos fatos e das evidências, distinguindo o que pode ser sustentado pelas informações efetivamente disponíveis.","summaryOrigin":"editorial"},{"name":"Crimes Contra a Vida, Investigação e Ação Penal","hours":25,"summary":"Estuda os crimes contra a vida e os caminhos da investigação e da ação penal relacionados a essas condutas. Aborda organização dos fatos, fontes de informação e atuação dos sujeitos da persecução. Discute a construção das hipóteses e dos argumentos jurídicos, com atenção à relação entre elementos investigativos, produção de provas e garantias no desenvolvimento do caso.","summaryOrigin":"editorial"},{"name":"Princípios Constitucionais do Tribunal do Júri","hours":25,"summary":"Examina os fundamentos constitucionais do Tribunal do Júri e sua relação com a organização do julgamento. Aborda defesa, participação dos jurados e limites de atuação dos sujeitos processuais. Discute como os princípios orientam a interpretação do procedimento e o controle dos atos, permitindo compreender a função das garantias na apresentação, na apreciação e na decisão sobre os fatos.","summaryOrigin":"editorial"},{"name":"Oratória, Argumentação e Persuasão Forense","hours":25,"summary":"Explora a organização da comunicação oral e a construção de argumentos na atuação forense. Aborda clareza, estrutura narrativa, escuta e relação entre afirmações e provas. Discute formas de apresentar questões jurídicas a diferentes interlocutores, com atenção à consistência do raciocínio, ao uso da linguagem e aos limites éticos da persuasão no contexto do Tribunal do Júri.","summaryOrigin":"editorial"},{"name":"Análise Crítica nos Procedimentos do Júri, Penas e Medidas de Segurança","hours":25,"summary":"Analisa criticamente os procedimentos do júri e suas relações com a aplicação de penas e medidas de segurança. Aborda fundamentos, finalidades e questões de interpretação presentes nessas respostas. Discute os argumentos utilizados na análise da responsabilidade e das consequências jurídicas, relacionando a leitura do caso à proteção de garantias e ao controle das decisões adotadas.","summaryOrigin":"editorial"},{"name":"Audiência de Instrução e Preparação para Plenário","hours":25,"summary":"Relaciona a audiência de instrução à preparação do caso para o julgamento em plenário. Aborda organização de informações, análise de depoimentos e identificação das questões que precisam ser esclarecidas. Discute a construção dos argumentos a partir das provas e dos acontecimentos do processo, com atenção à coerência entre a atuação na instrução e a apresentação posterior do caso.","summaryOrigin":"editorial"},{"name":"Defesa, Acusação, Assistente de Acusação e Magistratura no Plenário do Júri","hours":25,"summary":"Examina os papéis da defesa, da acusação, do assistente de acusação e da magistratura no plenário do júri. Aborda atribuições, formas de participação e limites de atuação de cada sujeito. Discute como essas funções se relacionam durante o julgamento, permitindo analisar a organização dos debates, a condução dos atos e o respeito às garantias dos envolvidos.","summaryOrigin":"editorial"},{"name":"Nulidades e Individualização da Pena no Rito do Júri","hours":25,"summary":"Estuda as questões de nulidade e os critérios de individualização da pena no procedimento do júri. Relaciona regularidade dos atos, proteção de garantias e fundamentação das consequências jurídicas. Discute a identificação de problemas processuais e a construção dos argumentos para seu controle, considerando a importância do contexto e dos efeitos efetivos de cada ocorrência.","summaryOrigin":"editorial"},{"name":"Procedimento do Júri e Recursos Criminais","hours":25,"summary":"Explora as fases do procedimento do júri e as possibilidades de impugnação das decisões proferidas nesse percurso. Aborda finalidades, pressupostos e organização dos recursos. Discute a relação entre as questões do caso e os fundamentos apresentados, permitindo compreender os limites da revisão e as diferenças entre o controle do procedimento e a apreciação das conclusões do julgamento.","summaryOrigin":"editorial"},{"name":"Bases Doutrinárias e Jurisprudenciais da Execução Penal","hours":25,"summary":"Apresenta fundamentos doutrinários e jurisprudenciais para o estudo da execução penal. Aborda finalidades, competências e garantias relacionadas ao cumprimento das decisões penais. Discute a leitura crítica de entendimentos e argumentos, permitindo relacionar as referências da área às questões concretas da execução, sem tratar a aplicação da pena como uma etapa desvinculada de direitos.","summaryOrigin":"editorial"},{"name":"Regimes Prisionais, Sistema Penitenciário, Direitos e Deveres do Apenado","hours":25,"summary":"Examina os regimes de cumprimento da pena e a organização do sistema penitenciário. Aborda direitos, deveres e responsabilidades presentes na execução penal e nas relações com as instituições. Discute as condições de acompanhamento e de controle das decisões, relacionando a situação da pessoa apenada às garantias, às finalidades da pena e aos limites da atuação estatal.","summaryOrigin":"editorial"},{"name":"Produção Científica","hours":25,"summary":"Apresenta as etapas de construção de uma pesquisa relacionada ao Tribunal do Júri, à custódia ou à execução penal. Aborda definição do problema, seleção e avaliação de fontes e organização da escrita. Discute a relação entre evidências e argumentos, com atenção à ética acadêmica e à elaboração de um texto que comunique de forma clara a questão estudada e as conclusões alcançadas.","summaryOrigin":"editorial"},{"name":"Trabalho de Conclusão de Curso","hours":10,"summary":"Integra os conhecimentos da especialização na elaboração de um trabalho final sobre uma questão da área. Discute delimitação do tema, objetivos e organização de uma análise fundamentada. Aborda a articulação entre fontes, argumentos e conclusão, permitindo apresentar uma produção coerente com o percurso do curso e explicitar sua contribuição para o debate ou para a reflexão profissional.","summaryOrigin":"editorial"}],"sumHours":360,"source":"WhatsApp Image 2026-10-30 at 17.44.45.jpeg","notes":[],"hasTotalConflict":false}};
const curriculumCopy={
 'educacao':{desc:'Educação afrocentrada, tecnologias e leitura dos territórios.',lead:'Uma formação que articula educação afrocentrada, tecnologias e territórios, conectando fundamentos, produção de conteúdos, projetos e experiências de campo.',overviewTitle:'Educação afrocentrada, tecnologias e territórios.',paragraphs:['A especialização articula educação afrocentrada, relações étnico-raciais, tecnologias e saberes dos territórios. A matriz reúne fundamentos, história e cultura africana e afro-brasileira, multiletramentos e produção de conteúdos.', 'Laboratório de projetos, aulas de campo e projeto final integram o percurso, aproximando reflexão, autoria e prática educativa.'],audience:'Graduados e profissionais da educação interessados em educação afrocentrada, relações étnico-raciais, tecnologias educacionais e práticas ligadas aos territórios.',audienceTags:['Educação Afrocentrada','Tecnologias','Territórios'],question:'O que caracteriza esta especialização?',answer:'A formação relaciona educação afrocentrada, tecnologias e territórios, com componentes teóricos e práticos, laboratório, atividades de campo e projeto final.'},
 'enfermagem-aph':{desc:'Enfermagem no APH móvel, nas ambulâncias e no cuidado ao paciente crítico.',lead:'Aprofunde a atuação da enfermagem no atendimento pré-hospitalar móvel, na urgência e emergência e na assistência ao paciente crítico em ambulâncias.',overviewTitle:'Formação voltada ao atendimento pré-hospitalar móvel.',paragraphs:['A especialização reúne avaliação do paciente, suporte de vida, atendimento ao trauma e emergências clínicas, pediátricas e obstétricas no contexto pré-hospitalar.', 'A organização de ambulâncias, o transporte do paciente crítico, a comunicação e os cenários de simulação também fazem parte da matriz curricular.'],audience:'Enfermeiros graduados interessados em atendimento pré-hospitalar móvel, urgência, emergência, transporte de pacientes críticos e assistência em ambulâncias.',audienceTags:['Enfermagem','APH móvel','Urgência e Emergência']},
 'enfermagem-mulher':{desc:'Assistência de enfermagem à mulher em cenários de média e alta complexidade.',lead:'Uma especialização em cuidado integral à mulher, com foco na assistência ginecológica, obstétrica, oncológica, cirúrgica, crítica e paliativa.',overviewTitle:'Saúde da mulher, alta complexidade e cuidado integral.',paragraphs:['O curso aborda a assistência de enfermagem à mulher em diferentes fases da vida e cenários de média e alta complexidade. A matriz reúne saúde ginecológica, gestação de alto risco, emergências e cuidados perioperatórios.', 'Oncologia ginecológica e mamária, terapia intensiva, cuidados paliativos, navegação da paciente e gestão do cuidado integram o percurso formativo.'],audience:'Enfermeiros que desejam aprofundar sua formação na assistência integral à mulher e no cuidado em contextos de média e alta complexidade.',audienceTags:['Enfermagem','Saúde da Mulher','Alta Complexidade']},
 'direito-penal-processo':{desc:'Fundamentos constitucionais, garantias e prática penal e processual penal.',lead:'Aprofunde o estudo do sistema penal e processual penal sob uma perspectiva constitucional, integrando fundamentos, garantias e prática jurídica.',overviewTitle:'Teoria e prática a partir dos fundamentos constitucionais.',paragraphs:['A especialização reúne fundamentos constitucionais, sistema acusatório, garantias fundamentais, criminologia e política criminal.', 'A matriz avança por investigação, prova, cautelares, prisões, procedimentos, júri, recursos e execução penal, relacionando os conteúdos à prática jurídica.'],audience:'Graduados e profissionais do Direito interessados em fundamentos constitucionais, garantias e atuação penal e processual penal.',audienceTags:['Direito Penal','Processo Penal','Constituição']},
 'direitos-mulheres':{desc:'Direitos humanos das mulheres, proteção e justiça de gênero.',lead:'Uma formação que articula direitos humanos das mulheres, interseccionalidade, proteção e justiça de gênero, aproximando fundamentos e atuação prática.',overviewTitle:'Direitos humanos das mulheres e justiça de gênero.',paragraphs:['A matriz se organiza em eixos sobre fundamentos, interseccionalidade, raça, território, violências, família, autonomia econômica, saúde e justiça de gênero.', 'Redes de enfrentamento, políticas públicas, litigância estratégica e produção científica integram uma proposta de formação conectada às diferentes dimensões dos direitos das mulheres.'],audienceTags:['Direitos das Mulheres','Justiça de Gênero','Direitos Humanos']},
 'perspectiva-genero':{desc:'Perspectiva de gênero aplicada ao Direito, à proteção e ao sistema de justiça.',lead:'Explore a perspectiva de gênero e as novas fronteiras do Direito, conectando violências, sistema de justiça, prova, tecnologia e direitos das mulheres.',overviewTitle:'Perspectiva de gênero e novas fronteiras do Direito.',paragraphs:['O curso articula fundamentos de gênero e direitos humanos com os desafios da atuação jurídica. A matriz inclui proteção, violências, processo, prova, família, trabalho e participação política.', 'Prova digital, inteligência artificial, advocacia estratégica e produção técnico-jurídica ampliam o diálogo com as questões contemporâneas do sistema de justiça.'],audience:'Graduados e profissionais do Direito, do sistema de justiça e de áreas relacionadas interessados em perspectiva de gênero e direitos das mulheres.',audienceTags:['Direito','Perspectiva de Gênero','Sistema de Justiça']},
 'gestao-estrategica':{desc:'Planejamento, dados, proteção e inovação nas políticas para mulheres.',lead:'Uma especialização em gestão pública de políticas para mulheres, integrando planejamento, orçamento, dados, monitoramento, proteção e inovação.',overviewTitle:'Gestão estratégica das políticas para mulheres.',paragraphs:['A formação reúne gestão pública e perspectiva de gênero para o planejamento, a coordenação e a avaliação de políticas para mulheres.', 'A matriz articula governança, orçamento, indicadores, redes de atendimento, prevenção, tecnologia e autonomia econômica, com um laboratório de soluções e produção técnico-profissional.'],audience:'Gestores públicos, profissionais de políticas para mulheres, integrantes do sistema de justiça e demais graduados interessados em gestão de políticas públicas para mulheres.',audienceTags:['Gestão Pública','Políticas para Mulheres','Dados e Inovação'],question:'Qual é o foco da especialização?',answer:'O foco é a gestão estratégica das políticas para mulheres, articulando planejamento, orçamento, dados, monitoramento, redes de proteção e inovação.'}
};
courses.forEach(course=>{
 const matrix=curriculaData[course.id];
 Object.assign(course,curriculumCopy[course.id]||{}, {name:matrix.officialName,curriculum:matrix.components,hours:matrix.declaredHours,hoursSum:matrix.sumHours,hasTotalConflict:matrix.hasTotalConflict});
});

