let destroyRelatedCarousel=null;

function renderRelatedCourses(related){
 return '<section class="related-section" aria-labelledby="related-title"><div class="wrap"><div class="related-heading"><h2 id="related-title">Outras possibilidades<br>para sua formação.</h2><div class="related-controls" role="group" aria-label="Navegar pelos cursos recomendados"><button type="button" class="related-arrow related-prev" aria-label="Cursos anteriores" aria-controls="related-track" disabled>'+icon('arrow')+'</button><button type="button" class="related-arrow related-next" aria-label="Próximos cursos" aria-controls="related-track">'+icon('arrow')+'</button></div></div><div class="course-grid related-track" id="related-track" role="group" aria-roledescription="carrossel" aria-label="Cursos de pós-graduação recomendados" tabindex="0">'+related.map(courseCard).join('')+'</div></div></section>';
}

function initRelatedCarousel(){
 if(destroyRelatedCarousel)destroyRelatedCarousel();
 const track=byId('related-track');
 if(!track){destroyRelatedCarousel=null;return;}
 const section=track.closest('.related-section');
 const previous=section.querySelector('.related-prev');
 const next=section.querySelector('.related-next');
 let frame=0;
 const maximum=()=>Math.max(0,track.scrollWidth-track.clientWidth);
 const update=()=>{
  frame=0;
  previous.disabled=track.scrollLeft<=2;
  next.disabled=track.scrollLeft>=maximum()-2;
 };
 const onScroll=()=>{if(!frame)frame=requestAnimationFrame(update);};
 const moveTo=left=>track.scrollTo({left:Math.max(0,Math.min(maximum(),left)),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
 const move=direction=>{
  const card=track.querySelector('.course-card');
  if(!card)return;
  const stride=card.getBoundingClientRect().width+(parseFloat(getComputedStyle(track).columnGap)||0);
  const index=Math.round(track.scrollLeft/stride);
  moveTo((index+direction)*stride);
 };
 const back=()=>move(-1);
 const forward=()=>move(1);
 const onKey=event=>{
  if(event.target!==track)return;
  if(event.key==='ArrowLeft'){event.preventDefault();back();}
  else if(event.key==='ArrowRight'){event.preventDefault();forward();}
  else if(event.key==='Home'){event.preventDefault();moveTo(0);}
  else if(event.key==='End'){event.preventDefault();moveTo(maximum());}
 };
 previous.addEventListener('click',back);
 next.addEventListener('click',forward);
 track.addEventListener('scroll',onScroll,{passive:true});
 track.addEventListener('keydown',onKey);
 const observer=new ResizeObserver(update);
 observer.observe(track);
 update();
 destroyRelatedCarousel=()=>{
  observer.disconnect();
  if(frame)cancelAnimationFrame(frame);
  previous.removeEventListener('click',back);
  next.removeEventListener('click',forward);
  track.removeEventListener('scroll',onScroll);
  track.removeEventListener('keydown',onKey);
 };
}

