const byId=id=>document.getElementById(id);
const normalize=value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const esc=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const icon=name=>'<svg class="icon" aria-hidden="true"><use href="#i-'+name+'"/></svg>';
const areaName=id=>areas.find(area=>area.id===id)?.name||'';
const coursePaths={"tribunal-juri-custodia":"/faculdade/pos-graduacao/tribunal-do-juri-e-audiencia-de-custodia/","direito-militar":"/faculdade/pos-graduacao/direito-militar/","seguranca-publica":"/faculdade/pos-graduacao/seguranca-publica-e-politica-criminal/","enfermagem-aph":"/faculdade/pos-graduacao/enfermagem-em-atendimento-pre-hospitalar-movel-urgencia-e-emergencia/","enfermagem-mulher":"/faculdade/pos-graduacao/enfermagem-em-saude-da-mulher-alta-complexidade-e-cuidado-integral/","direito-penal-processo":"/faculdade/pos-graduacao/penal-e-processo-penal-constitucional-teoria-e-pratica/","educacao":"/faculdade/pos-graduacao/educacao-afrocentrada-tecnologias-e-territorios/","direitos-mulheres":"/faculdade/pos-graduacao/direitos-humanos-das-mulheres-e-justica-de-genero/","perspectiva-genero":"/faculdade/pos-graduacao/perspectiva-de-genero-e-novas-fronteiras-do-direito/","gestao-estrategica":"/faculdade/pos-graduacao/gestao-estrategica-das-politicas-para-mulheres/"};
let currentCourse=courses.find(course=>course.id===document.body.dataset.course)||null,currentView=currentCourse?'course':'catalog',currentArea='all';

function courseCard(course){return compactCourseCard(course);}
function renderAreas(){
 byId('area-filters').innerHTML=areas.map(area=>`<button type="button" class="area-button ${area.id===currentArea?'active':''}" data-area="${area.id}" aria-pressed="${area.id===currentArea}"><span>${esc(area.name)}</span><span class="area-count">${area.id==='all'?courses.length:courses.filter(course=>course.area===area.id).length}</span></button>`).join('');
}
function renderCatalog(){
 const query=normalize(byId('course-search').value),words=query.split(/\s+/).filter(Boolean);
 let visible=courses.filter(course=>{const searchable=normalize(course.name+' '+course.desc+' '+areaName(course.area)+' '+course.curriculum.map(component=>component.name).join(' '));return(currentArea==='all'||course.area===currentArea)&&words.every(word=>searchable.includes(word));});
 const order=byId('course-sort').value;
 if(order!=='featured')visible=[...visible].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')*(order==='az'?1:-1));
 byId('search-clear').hidden=!query;
 byId('results-count').textContent=visible.length+' '+(visible.length===1?'curso encontrado':'cursos encontrados');
 byId('catalog-results-title').textContent=currentArea==='all'?'Conheça os cursos':areaName(currentArea);
 byId('course-grid').innerHTML=visible.length?visible.map(courseCard).join(''):`<div class="empty-state">${icon('search')}<h3>Vamos tentar outra busca?</h3><p>Nenhum curso encontrado. Busque por outro nome ou escolha outra área.</p><button class="btn btn-red" id="clear-filters">Ver todas as especializações</button></div>`;
}
function resetFilters(){
 currentArea='all';byId('course-search').value='';byId('course-sort').value='featured';byId('course-sort').dispatchEvent(new Event('change',{bubbles:true}));renderAreas();renderCatalog();
}

function closeMenus(){
 byId('courses-dropdown').hidden=true;byId('courses-toggle').setAttribute('aria-expanded','false');byId('main-nav').classList.remove('open');byId('mobile-toggle').setAttribute('aria-expanded','false');byId('mobile-toggle').setAttribute('aria-label','Abrir menu');
}
function scrollSection(id){
 const target=byId(id);if(!target)return;
 const headerBottom=document.querySelector('.header').getBoundingClientRect().bottom;
 const subnav=currentView==='course'?document.querySelector('.course-subnav')?.getBoundingClientRect().height||0:0;
 window.scrollTo({top:target.getBoundingClientRect().top+window.scrollY-headerBottom-subnav-23,behavior:'smooth'});
 document.querySelectorAll('[data-section]').forEach(link=>link.classList.toggle('active',link.dataset.section===id));
}


function showDialog(id){const dialog=byId(id);if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');}
function openRequest(id){
 if(byId('request-form').dataset.fbeSending==='true'){showDialog('request-dialog');return;}
 const courseId=id||currentCourse?.id||'';
 document.querySelectorAll('dialog[open]').forEach(dialog=>dialog.close());
 byId('request-form').reset();byId('form-success').hidden=true;byId('request-course').value=courses.find(course=>course.id===courseId)?.name||'';byId('request-course').dispatchEvent(new Event('change',{bubbles:true}));showDialog('request-dialog');
}
document.addEventListener('click',event=>{
 const request=event.target.closest('[data-request]');if(request){event.preventDefault();openRequest(request.dataset.request);return;}
 const section=event.target.closest('[data-section]');if(section){scrollSection(section.dataset.section);return;}
 const area=event.target.closest('[data-area]');if(area){currentArea=area.dataset.area;renderAreas();renderCatalog();return;}
 if(event.target.closest('#clear-filters')){resetFilters();return;}
 const close=event.target.closest('[data-close]');if(close){close.closest('dialog').close();return;}
 if(!event.target.closest('.courses-menu')){byId('courses-dropdown').hidden=true;byId('courses-toggle').setAttribute('aria-expanded','false');}
});
byId('courses-toggle').addEventListener('click',()=>{const open=byId('courses-toggle').getAttribute('aria-expanded')==='true';byId('courses-dropdown').hidden=open;byId('courses-toggle').setAttribute('aria-expanded',String(!open));});
byId('mobile-toggle').addEventListener('click',()=>{const open=byId('main-nav').classList.toggle('open');byId('mobile-toggle').setAttribute('aria-expanded',String(open));byId('mobile-toggle').setAttribute('aria-label',open?'Fechar menu':'Abrir menu');byId('mobile-toggle').textContent=open?'✕':'☰';});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenus();});
byId('course-search')?.addEventListener('input',renderCatalog);byId('course-sort')?.addEventListener('change',renderCatalog);
byId('search-clear')?.addEventListener('click',()=>{byId('course-search').value='';renderCatalog();byId('course-search').focus();});
byId('search-form')?.addEventListener('submit',event=>{event.preventDefault();renderCatalog();scrollSection('catalogo');});
document.querySelectorAll('dialog').forEach(dialog=>{dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open');});dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});});
byId('request-course').innerHTML='<option value="">Selecione uma pós-graduação</option>'+courses.map(course=>'<option value="'+esc(course.name)+'">'+esc(course.name)+'</option>').join('')+'<option value="Ainda estou escolhendo">Ainda estou escolhendo</option>';
// Cada grupo mantém apenas uma pergunta ou tema aberto, inclusive nas páginas internas.
document.addEventListener('toggle',event=>{
 const item=event.target;
 if(!(item instanceof HTMLDetailsElement)||!item.open)return;
 const group=item.closest('.faq-list,.topic-list');
 if(!group)return;
 group.querySelectorAll('details[open]').forEach(other=>{if(other!==item)other.open=false;});
},true);

function redirectLegacyCourse(){
 const match=location.hash.match(/^#\/curso\/([^/]+)/);
 if(match&&coursePaths[match[1]]){
  const target=new URL(coursePaths[match[1]],location.origin);
  target.search=location.search;
  if(location.hash.endsWith('/instituicao'))target.hash='curso-fbe';
  location.replace(target);
 }
}
redirectLegacyCourse();
window.addEventListener('hashchange',redirectLegacyCourse);
if(byId('course-grid')){renderAreas();renderCatalog();}
if(currentCourse)initRelatedCarousel();
byId('mobile-catalog').textContent=currentCourse?'Todas as pós':'Ver especializações';
byId('mobile-catalog').href='/faculdade/pos-graduacao/';
if(location.hash==='#/ingresso')openRequest();

function renderDiscipline(component){
 const name='<span class="discipline-name">'+esc(component.name)+'</span>';
 const hours='<span class="discipline-hours">'+component.hours+' h</span>';
 if(!component.summary)return '<div class="discipline-static">'+name+hours+'<span aria-hidden="true"></span></div>';
 const control='<span class="discipline-control" aria-hidden="true"><svg class="icon discipline-plus" viewBox="0 0 24 24"><path d="M4 12h16M12 4v16"/></svg><svg class="icon discipline-minus" viewBox="0 0 24 24"><path d="M4 12h16"/></svg></span>';
 return '<details><summary>'+name+hours+control+'</summary><p>'+esc(component.summary)+'</p></details>';
}


/* Seletores FBE. O select original mantém valor, validação e compatibilidade de formulário. */
const fbeSelectControls=[];
function createFbeSelect(select){
 const searchable=select.id==='request-course';
 const wrapper=document.createElement('div');wrapper.className='fbe-select';
 select.parentNode.insertBefore(wrapper,select);wrapper.append(select);
 select.classList.add('fbe-select-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');
 const trigger=document.createElement('button');trigger.type='button';trigger.id=select.id+'-trigger';trigger.className='fbe-select-trigger';
 trigger.setAttribute('role','combobox');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
 trigger.setAttribute('aria-controls',select.id+'-options');
 if(select.required)trigger.setAttribute('aria-required','true');
 const value=document.createElement('span');value.className='fbe-select-value';
 const chevron=document.createElementNS('http://www.w3.org/2000/svg','svg');chevron.setAttribute('class','icon fbe-select-chevron');chevron.setAttribute('aria-hidden','true');
 const chevronUse=document.createElementNS('http://www.w3.org/2000/svg','use');chevronUse.setAttribute('href','#i-chevron');chevron.append(chevronUse);trigger.append(value,chevron);wrapper.append(trigger);
 const popup=document.createElement('div');popup.className='fbe-select-popup';popup.hidden=true;wrapper.append(popup);
 const searchRow=document.createElement('div');searchRow.className='fbe-select-search';
 let search=null;
 if(searchable){
  searchRow.innerHTML=icon('search');search=document.createElement('input');search.type='search';search.className='fbe-select-search-input';search.placeholder='Busque uma especialização';search.autocomplete='off';search.setAttribute('aria-label','Buscar uma pós-graduação');searchRow.append(search);popup.append(searchRow);
 }
 const list=document.createElement('div');list.className='fbe-select-list';list.id=select.id+'-options';list.setAttribute('role','listbox');list.setAttribute('aria-label',searchable?'Cursos de pós-graduação':select.id==='course-sort'?'Ordenar os cursos':'Formação de interesse');popup.append(list);
 const empty=document.createElement('div');empty.className='fbe-select-empty';empty.textContent='Nenhum curso encontrado. Tente outro nome.';empty.hidden=true;popup.append(empty);
 if(searchable){const hint=document.createElement('p');hint.className='fbe-select-hint';hint.textContent='Escolha o curso que combina com o seu próximo passo.';popup.append(hint);}
 const error=document.createElement('p');error.id=select.id+'-error';error.className='fbe-select-error';error.textContent='Selecione uma pós-graduação para continuar.';error.hidden=true;wrapper.append(error);
 const label=select.closest('label');
 if(label){
  const labelText=[...label.childNodes].find(node=>node.nodeType===Node.TEXT_NODE&&node.textContent.trim());
  if(labelText){const title=document.createElement('span');title.id=select.id+'-label';title.textContent=labelText.textContent.trim();label.replaceChild(title,labelText);trigger.setAttribute('aria-labelledby',title.id+' '+select.id+'-value');}
  label.htmlFor=trigger.id;
 }else trigger.setAttribute('aria-label',list.getAttribute('aria-label'));
 value.id=select.id+'-value';
 function sync(){
  const option=select.options[select.selectedIndex]||select.options[0];
  value.textContent=option?.textContent||'Selecione';value.classList.toggle('fbe-select-placeholder',!select.value);
  if(select.value){wrapper.classList.remove('is-invalid');error.hidden=true;trigger.removeAttribute('aria-invalid');trigger.removeAttribute('aria-describedby');}
  renderOptions();
 }
 function renderOptions(){
  const query=normalize(search?.value||'');list.replaceChildren();
  [...select.options].filter(option=>option.value&&!option.disabled&&normalize(option.textContent).includes(query)).forEach(option=>{
   const button=document.createElement('button');button.type='button';button.className='fbe-select-option';button.setAttribute('role','option');button.setAttribute('aria-selected',String(select.value===option.value));button.tabIndex=-1;button.dataset.value=option.value;
   const name=document.createElement('span');name.textContent=option.textContent;
   const check=document.createElementNS('http://www.w3.org/2000/svg','svg');check.setAttribute('class','icon');check.setAttribute('viewBox','0 0 24 24');check.setAttribute('aria-hidden','true');
   const checkPath=document.createElementNS('http://www.w3.org/2000/svg','path');checkPath.setAttribute('d','m5 12 4 4L19 6');check.append(checkPath);button.append(name,check);
   button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));close(true);});
   list.append(button);
  });empty.hidden=list.childElementCount>0;
 }
 function place(){
  const rect=trigger.getBoundingClientRect();const dialog=trigger.closest('dialog');const bounds=dialog?dialog.getBoundingClientRect():{top:0,bottom:window.innerHeight};
  const below=Math.min(window.innerHeight-12,bounds.bottom-12)-rect.bottom-8;
  const above=rect.top-Math.max(12,bounds.top+12)-8;
  const desired=searchable?354:220;const up=below<desired&&above>below;
  wrapper.dataset.side=up?'top':'bottom';popup.style.maxHeight=Math.min(desired,Math.max(110,up?above:below))+'px';
 }
 function focusOption(direction){
  const options=[...list.querySelectorAll('[role="option"]')];if(!options.length)return;
  let index=options.indexOf(document.activeElement);
  if(direction==='first')index=0;else if(direction==='last')index=options.length-1;
  else if(index<0){const selected=options.findIndex(option=>option.getAttribute('aria-selected')==='true');index=direction<0?options.length-1:Math.max(0,selected);}
  else index=(index+direction+options.length)%options.length;
  options[index].focus({preventScroll:true});options[index].scrollIntoView({block:'nearest'});
 }
 function open(focus='search'){
  fbeSelectControls.forEach(control=>control.close(false));
  if(search)search.value='';renderOptions();popup.hidden=false;trigger.setAttribute('aria-expanded','true');place();
  if(focus==='search'&&search)search.focus({preventScroll:true});else if(focus==='first')focusOption('first');else if(focus==='last')focusOption('last');else if(focus==='selected')focusOption(1);
 }
 function close(restoreFocus=false){popup.hidden=true;trigger.setAttribute('aria-expanded','false');if(restoreFocus)trigger.focus({preventScroll:true});}
 trigger.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();if(popup.hidden)open(searchable?'search':'selected');else close(false);});
 trigger.addEventListener('keydown',event=>{
  if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();open(event.key==='End'||event.key==='ArrowUp'?'last':'first');}
  else if(searchable&&event.key.length===1&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&event.key!==' '){event.preventDefault();open();search.value=event.key;renderOptions();}
 });
 popup.addEventListener('keydown',event=>{
  if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true);}
  else if(event.key==='Tab'){close(false);}
  else if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();focusOption(event.key==='ArrowDown'?1:-1);}
  else if((event.key==='Home'||event.key==='End')&&event.target!==search){event.preventDefault();focusOption(event.key==='Home'?'first':'last');}
 });
 search?.addEventListener('input',renderOptions);
 select.addEventListener('change',sync);
 select.addEventListener('invalid',event=>{event.preventDefault();wrapper.classList.add('is-invalid');error.hidden=false;trigger.setAttribute('aria-invalid','true');trigger.setAttribute('aria-describedby',error.id);trigger.focus();open();});
 select.form?.addEventListener('reset',()=>queueMicrotask(()=>{close();search&&(search.value='');wrapper.classList.remove('is-invalid');error.hidden=true;trigger.removeAttribute('aria-invalid');trigger.removeAttribute('aria-describedby');sync();}));
 wrapper.addEventListener('focusout',event=>{if(event.relatedTarget&&!wrapper.contains(event.relatedTarget))close(false);});
 const control={wrapper,close,sync,place};fbeSelectControls.push(control);sync();return control;
}
document.querySelectorAll('select').forEach(createFbeSelect);
document.addEventListener('click',event=>{fbeSelectControls.forEach(control=>{if(!control.wrapper.contains(event.target))control.close(false);});});
document.addEventListener('keydown',event=>{if(event.key==='Escape')fbeSelectControls.forEach(control=>control.close(false));});
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('close',()=>fbeSelectControls.forEach(control=>control.close(false))));
window.addEventListener('resize',()=>fbeSelectControls.forEach(control=>{if(control.wrapper.querySelector('[aria-expanded="true"]'))control.place();}));

